    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The general store was essential to daily life in the rural United States during the 1800s because it provided the supplies that the people living in nearby communities needed. Also, the store was a ______ of information. People socializing at the general store would share news and help spread it throughout their communities."}]}'::jsonb, 'source') returning id into v_stim;
