    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 1);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "For painter Jacob Lawrence, being ______ was an important part of the artistic process. Because he paid close attention to all the details of his Harlem neighborhood, Lawrence’s artwork captured nuances in the beauty and vitality of the Black experience during the Harlem Renaissance and the Great Migration."}]}'::jsonb, 'source') returning id into v_stim;
