    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 3);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The parasitic dodder plant increases its reproductive success by flowering at the same time as the host plant it has latched onto. In 2020, Jianqiang Wu and his colleagues determined that the tiny dodder achieves this ______ with its host by absorbing and utilizing a protein the host produces when it is about to flower."}]}'::jsonb, 'source') returning id into v_stim;
