    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 4);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Barring major archaeological discoveries, we are unlikely to ever have ______ account of ancient Egypt under the female pharaoh Hatshepsut, as much of the evidence of her reign was deliberately destroyed by her successors."}]}'::jsonb, 'source') returning id into v_stim;
