    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "making individual E. esula plants more susceptible to existing chemical herbicides."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "enhancing the ecological benefits of E. esula in North America."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "enabling cattle to consume E. esula without becoming sick."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "reducing invasive E. esula numbers without harming other organisms."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 18);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "A team of biologists led by Jae-Hoon Jung, Antonio D. Barbosa, and Stephanie Hutin investigated the mechanism that allows Arabidopsis thaliana (thale cress) plants to accelerate flowering at high temperatures. They replaced the protein ELF3 in the plants with a similar protein found in another species (stiff brome) that, unlike A. thaliana, displays no acceleration in flowering with increased temperature. A comparison of unmodified A. thaliana plants with the altered plants showed no difference in flowering at 22° Celsius, but at 27° Celsius, the unmodified plants exhibited accelerated flowering while the altered ones did not, which suggests that ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "temperature-sensitive accelerated flowering is unique to A. thaliana."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "A. thaliana increases ELF3 production as temperatures rise."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "ELF3 enables A. thaliana to respond to increased temperatures."}]}'::jsonb, true), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "temperatures of at least 22° Celsius are required for A. thaliana to flower."}]}'::jsonb, false);
