    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["In 2013, archaeologists studied cat bone fragments they had found in the ruins of Quanhucun, a Chinese farming village.", "The fragments were estimated to be 5,300 years old.", "A chemical analysis of the fragments revealed that the cats had consumed large amounts of grain.", "The grain consumption is evidence that the Quanhucun cats may have been domesticated."]}, {"type": "paragraph", "text": "The student wants to present the Quanhucun study and its conclusions."}]}'::jsonb, 'source') returning id into v_stim;
