    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "As part of a 2013 study of cat domestication, a chemical analysis was conducted on cat bone fragments found in Quanhucun, China."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "A 2013 analysis of cat bone fragments found in Quanhucun, China, suggests that cats there may have been domesticated 5,300 years ago."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "In 2013, archaeologists studied what cats in Quanhucun, China, had eaten more than 5,000 years ago."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Cat bone fragments estimated to be 5,300 years old were found in Quanhucun, China, in 2013."}]}'::jsonb, false);
