    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["Gaspar Enriquez is an artist.", "He specializes in portraits of Mexican Americans.", "A portrait is an artistic representation of a person.", "Enriquez completed a painting of the sculptor Luis Jimenez in 2003.", "He completed a drawing of the writer Rudolfo Anaya in 2016."]}, {"type": "paragraph", "text": "The student wants to emphasize a difference between the two portraits."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
