    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "While researching a topic, a student has taken the following notes:"}, {"type": "list", "items": ["The Gullah are a group of African Americans who have lived in parts of the southeastern United States since the 18th century.", "Gullah culture is influenced by West African and Central African traditions.", "Louise Miller Cohen is a Gullah historian, storyteller, and preservationist.", "She founded the Gullah Museum of Hilton Head Island, South Carolina, in 2003.", "Vermelle Rodrigues is a Gullah historian, artist, and preservationist.", "She founded the Gullah Museum of Georgetown, South Carolina, in 2003."]}, {"type": "paragraph", "text": "The student wants to emphasize the duration and purpose of Cohen’s and Rodrigues’s work."}]}'::jsonb, 'source') returning id into v_stim;
