    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 35);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The province of Xoconochco was situated on the Pacific coast, hundreds of kilometers southeast of Tenochtitlan, the capital of the Aztec Empire. Because Xoconochco’s location within the empire was so ______, cacao and other trade goods produced there could reach the capital only after a long overland journey."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "unobtrusive"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "concealed"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "approximate"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "peripheral"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 36);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Proposals to raise the age at which retirees begin receiving government transfers of funds are generally discussed in terms of the effects on transfer recipients, but Andria Smythe has argued that delaying such transfers could ______ wealth creation among working adults by lengthening the period in which they are providing financial support to their nonworking parents."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "stymie"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "compound"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "disparage"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "outstrip"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 37);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Political blogs with conspicuous ideological alignments became an integral component of US media in the early 2000s. While some commentators lauded this development, asserting that such blogs had a welcome transparency missing from traditional news, less ______ observers countered that such blogs tended to ideological extremes that exacerbated political polarization to problematic levels."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "sanguine"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "recalcitrant"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "misanthropic"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "earnest"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 38);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is adapted from Pam Muñoz Ryan’s 2020 novel Mañanaland. In the village where Max lives, there is an old fortress called La Reina. Children in the village say that the fortress is haunted."}, {"type": "paragraph", "text": "For as long as he could remember, Max had begged Papá [his father] to take him to see La Reina and the ruins up close. He’d be a hero among his friends if he was the first boy to cross the haunted gates! Just because Papá didn’t believe in ghosts didn’t mean they weren’t there. Maybe this summer Papá would finally take him. He was almost twelve."}, {"type": "paragraph", "text": "©2020 by Pam Muñoz Ryan"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "To portray how proud Max’s father is of Max"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "To explain why Max doesn’t want to grow up yet"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "To criticize Max for disliking summer"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "To show how much Max wants to visit La Reina"}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 39);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is adapted from George Bernard Shaw’s 1912 play Pygmalion. Henry Higgins has just arrived at the house of his mother (Mrs. Higgins). She is expecting her friends to visit soon."}, {"type": "paragraph", "text": "MRS. HIGGINS: I’m serious, Henry. You offend all my friends: they stop coming whenever they meet you."}, {"type": "paragraph", "text": "HIGGINS: Nonsense! I know I have no small talk; but people don’t mind."}, {"type": "paragraph", "text": "MRS. HIGGINS: Oh! don’t they? Small talk indeed! What about your large talk? Really, dear, you mustn’t stay."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "To describe what Henry’s mother does when she goes out with her friends"}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "To show that Henry’s mother wants him to leave"}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "To present a detailed account of what Henry’s home looks like"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "To explain why Henry often visits his mother"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 40);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is from Charlotte Forten Grimké’s 1888 poem “At Newport.”"}, {"type": "paragraph", "text": "Oh, deep delight to watch the gladsome waves / Exultant leap upon the rugged rocks; / [[0|Ever repulsed, yet ever rushing on—]] / [[0|Filled with a life that will not know defeat]]; / To see the glorious hues of sky and sea. / The distant snowy sails, glide spirit like, / Into an unknown world, to feel the sweet / Enchantment of the sea thrill all the soul, / Clearing the clouded brain, making the heart / Leap joyous as it own bright, singing waves!"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "It portrays the surroundings as an imposing and intimidating scene."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "It characterizes the sea’s waves as a relentless and enduring force."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "It conveys the speaker’s ambivalence about the natural world."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "It draws a contrast between the sea’s waves and the speaker’s thoughts."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 41);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Believing that living in an impractical space can heighten awareness and even improve health, conceptual artists Madeline Gins and Shusaku Arakawa designed an apartment building in Japan to be more fanciful than functional. A kitchen counter is chest-high on one side and knee-high on the other; a ceiling has a door to nowhere. The effect is disorienting but invigorating: after four years there, filmmaker Nobu Yamaoka reported significant health benefits."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Although inhabiting a home surrounded by fanciful features such as those designed by Gins and Arakawa can be rejuvenating, it is unsustainable."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Designing disorienting spaces like those in the Gins and Arakawa building is the most effective way to create a physically stimulating environment."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "As a filmmaker, Yamaoka has long supported the designs of conceptual artists such as Gins and Arakawa."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Although impractical, the design of the apartment building by Gins and Arakawa may improve the well-being of the building’s residents."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 42);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The following text is adapted from Lewis Carroll’s 1889 satirical novel Sylvie and Bruno. A crowd has gathered outside a room belonging to the Warden, an official who reports to the Lord Chancellor."}, {"type": "paragraph", "text": "One man, who was more excited than the rest, flung his hat high into the air, and shouted (as well as I could make out) “Who roar for the Sub-Warden?” Everybody roared, but whether it was for the Sub-Warden, or not, did not clearly appear: some were shouting “Bread!” and some “Taxes!”, but no one seemed to know what it was they really wanted."}, {"type": "paragraph", "text": "All this I saw from the open window of the Warden’s breakfast-saloon, looking across the shoulder of the Lord Chancellor."}, {"type": "paragraph", "text": "“What can it all mean?” he kept repeating to himself. “I never heard such shouting before—and at this time of the morning, too! And with such unanimity!”"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "He asks about the meaning of the crowd’s shouting, even though he claims to know what the crowd wants."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "He indicates a desire to speak to the crowd, even though the crowd has asked to speak to the Sub-Warden."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "He expresses sympathy for the crowd’s demands, even though the crowd’s shouting annoys him."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "He describes the crowd as being united, even though the crowd clearly appears otherwise."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 43);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-10/rw-m2-q11.png", "alt": "Table or graph for this question", "width": 280}, {"type": "paragraph", "text": "Global biomass is the total mass of living material, such as animals and plants, on Earth. A team of scientists estimated the global biomass, by species, of various wild land mammals. The team found that the species with the highest global biomass is the ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "wild boar."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "eastern gray kangaroo."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "African bush elephant."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "white-tailed deer."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 44);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-10/rw-m2-q12.png", "alt": "Table or graph for this question", "width": 560}, {"type": "paragraph", "text": "Studying tools unearthed at a cave site on the western coast of Italy, archaeologist Paola Villa and colleagues have determined that prehistoric Neanderthal groups fashioned them from shells of clams that they harvested from the seafloor while wading or diving or that washed up on the beach. Clamshells become thin and eroded as they wash up on the beach, while those on the seafloor are smooth and sturdy, so the research team suspects that Neanderthals prized the tools made with seafloor shells. However, the team also concluded that those tools were likely more challenging to obtain, noting that ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "at each depth below the surface in the cave, the difference in the numbers of tools of each type suggests that shells were easier to collect from the beach than to harvest from the seafloor."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "the highest number of tools were at a depth of 3–4 meters below the surface, which suggests that the Neanderthal population at the site was highest during the related period of time."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "at each depth below the surface in the cave, the difference in the numbers of tools of each type suggests that Neanderthals preferred to use clamshells from the beach because of their durability."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "the higher number of tools at depths of 5–6 meters below the surface in the cave than at depths of 4–5 meters below the surface suggests that the size of clam populations changed over time."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 45);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-10/rw-m2-q13.png", "alt": "Table or graph for this question", "width": 280}, {"type": "paragraph", "text": "Perovskite solar cells convert light into electricity more efficiently than earlier kinds of solar cells, and manufacturing advances have recently made them commercially attractive. One limitation of the cells, however, has to do with their electron transport layer (ETL), through which absorbed electrons must pass. Often the ETL is applied through a process called spin coating, but such ETLs are fairly inefficient at converting input power to output power. André Taylor and colleagues tested a novel spray coating method for applying the ETL. The team produced ETLs of various thicknesses and concluded that spray coating holds promise for improving the power conversion efficiency of ETLs in perovskite solar cells."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Both the ETL applied through spin coating and the ETL applied through spray coating showed a power conversion efficiency greater than 10% at their lowest performing thickness."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "The lowest performing ETL applied through spray coating had a higher power conversion efficiency than the highest performing ETL applied through spin coating."}]}'::jsonb, true), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "The highest performing ETL applied through spray coating showed a power conversion efficiency of approximately 13%, while the highest performing ETL applied through spin coating showed a power conversion efficiency of approximately 11%."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "There was a substantial difference in power conversion efficiency between the lowest and highest performing ETLs applied through spray coating."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 46);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'table', '{"blocks": [{"type": "image", "src": "/sat/test-10/rw-m2-q14.png", "alt": "Table or graph for this question", "width": 540}, {"type": "paragraph", "text": "Over the past two hundred years, the percentage of the population employed in the agricultural sector has declined in both France and the United States, while employment in the service sector (which includes jobs in retail, consulting, real estate, etc.) has risen. However, this transition happened at very different rates in the two countries. This can be seen most clearly by comparing the employment by sector in both countries in ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "1900 with the employment by sector in 1950."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "1800 with the employment by sector in 2012."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "1900 with the employment by sector in 2012."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "1800 with the employment by sector in 1900."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 47);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "The linguistic niche hypothesis (LNH) posits that the exotericity of languages (how prevalent non-native speakers are) and grammatical complexity are inversely related, which the LNH ascribes to attrition of complex grammatical rules as more non-native speakers adopt the language but fail to acquire those rules. Focusing on two characteristics that are positive indices of grammatical complexity, fusion (when new phonemes arise from the merger of previously distinct ones) and informativity (languages’ capacity for meaningful variation), Olena Shcherbakova and colleagues conducted a quantitative analysis for more than 1,300 languages and claim the outcome is inconsistent with the LNH."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "Shcherbakova and colleagues’ analysis showed a slightly negative correlation between grammatical complexity and fusion and between grammatical complexity and informativity."}]}'::jsonb, false), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "Shcherbakova and colleagues’ analysis showed a slightly negative correlation between grammatical complexity and exotericity."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "Shcherbakova and colleagues’ analysis showed a slightly positive correlation between grammatical complexity and fusion."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "Shcherbakova and colleagues’ analysis showed a slightly positive correlation between fusion and exotericity and between informativity and exotericity."}]}'::jsonb, true);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 48);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Archaeologist Christiana Kohler and her team excavated the Egyptian tomb of Queen Merneith, the wife of a First Dynasty pharaoh. Some scholars claim that she also ruled Egypt on her own and was actually the first female pharaoh. The team found a tablet in Merneith’s tomb with writing suggesting that she was in charge of the country’s treasury and other central offices. Whether Merneith was a pharaoh or not, this discovery supports the idea that Merneith likely ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "had an important role in Egypt’s government."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "lived after rather than before the First Dynasty of Egypt."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "traveled beyond Egypt’s borders often."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "created a new form of writing in Egypt."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 49);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "In a study of the cognitive abilities of white-faced capuchin monkeys (Cebus imitator), researchers neglected to control for the physical difficulty of the tasks they used to evaluate the monkeys. The cognitive abilities of monkeys given problems requiring little dexterity, such as sliding a panel to retrieve food, were judged by the same criteria as were those of monkeys given physically demanding problems, such as unscrewing a bottle and inserting a straw. The results of the study, therefore, ______"}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "could suggest that there are differences in cognitive ability among the monkeys even though such differences may not actually exist."}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "are useful for identifying tasks that the monkeys lack the cognitive capacity to perform but not for identifying tasks that the monkeys can perform."}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "should not be taken as indicative of the cognitive abilities of any monkey species other than C. imitator."}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "reveal more about the monkeys’ cognitive abilities when solving artificial problems than when solving problems encountered in the wild."}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 50);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Public-awareness campaigns about the need to reduce single-use plastics can be successful, says researcher Kim Borg of Monash University in Australia, when these campaigns give consumers a choice: for example, Japan achieved a 40 percent reduction in plastic-bag use after cashiers were instructed to ask customers whether ______ wanted a bag."}]}'::jsonb, 'source') returning id into v_stim;
    insert into public.questions (subject_id, stimulus_id, stimulus_marker, stem, explanation, topic_id, difficulty, origin, status, source_question_number, answer_format, accepted_answers)
    insert into public.question_options (question_id, label, content, is_correct) values (v_q, 'A', '{"blocks": [{"type": "paragraph", "text": "they"}]}'::jsonb, true), (v_q, 'B', '{"blocks": [{"type": "paragraph", "text": "one"}]}'::jsonb, false), (v_q, 'C', '{"blocks": [{"type": "paragraph", "text": "you"}]}'::jsonb, false), (v_q, 'D', '{"blocks": [{"type": "paragraph", "text": "it"}]}'::jsonb, false);
    insert into public.exam_questions (exam_id, section_id, question_id, position) values (v_exam, v_section, v_q, 51);
    insert into public.stimuli (subject_id, kind, content, origin) values (v_subject, 'passage', '{"blocks": [{"type": "paragraph", "text": "Lucía Michel of the University of Chile observed that alkaline soils contain an insoluble form of iron that blueberry plants cannot absorb, thus inhibiting blueberry growth. If these plants were grown in alkaline soil alongside grasses that aid in iron solubilization, ______ Michel was determined to find out."}]}'::jsonb, 'source') returning id into v_stim;
