select s.id, 'topic', v.name, v.ord from (values
  ('sat-math', 'Algebra', 1),
  ('sat-math', 'Advanced Math', 2),
  ('sat-math', 'Problem-Solving and Data Analysis', 3),
  ('sat-math', 'Geometry and Trigonometry', 4),
  ('sat-english', 'Craft and Structure', 1),
  ('sat-english', 'Information and Ideas', 2),
  ('sat-english', 'Standard English Conventions', 3),
  ('sat-english', 'Expression of Ideas', 4)
) as v(code, name, ord) join public.subjects s on s.code = v.code
on conflict (subject_id, kind, name) do nothing;

do $sat$
declare
  v_subject uuid; v_exam uuid; v_section uuid; v_stim uuid; v_q uuid;
begin
  -- SAT Practice Test 10: Reading and Writing
  if exists (select 1 from public.exams where slug = 'sat-practice-test-10-reading-and-writing') then
    raise notice 'skipping sat-practice-test-10-reading-and-writing (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-english';
    values (v_subject, 'sat-practice-test-10-reading-and-writing', 'SAT Practice Test 10: Reading and Writing', 'Official SAT Practice Test 10 (College Board), Reading and Writing: 66 questions in two modules, timed as the paper test (39 minutes per module).', 'full_mock', 'premium', 'draft', 78, 'source', 220, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 220], [210, 230], [220, 240], [220, 250], [230, 260], [230, 270], [240, 280], [240, 290], [250, 300], [250, 310], [260, 320], [270, 330], [280, 340], [300, 340], [310, 350], [320, 360], [330, 370], [330, 370], [340, 380], [350, 390], [350, 390], [360, 400], [370, 410], [370, 410], [380, 420], [390, 430], [400, 440], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [460, 500], [470, 510], [470, 530], [480, 540], [490, 550], [500, 560], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [570, 630], [580, 640], [590, 650], [600, 660], [610, 670], [620, 680], [630, 690], [640, 700], [670, 710], [680, 720], [690, 730], [700, 740], [720, 760], [730, 770], [740, 780], [760, 780], [770, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the role of the general store in US rural communities during the 1800s. In this context, “source” means a place where something originates or is obtained. The text states that people would share news while socializing at the general store. This context supports the idea that the store served as a source of information in rural communities."}, {"type": "paragraph", "text": "Choice B is incorrect because “rival” would mean competitor or opponent. The text doesn’t indicate that the general store was a rival of anything. Instead, the text describes the general store as a place that enabled the sharing of information within rural communities. Choice C is incorrect because in this context, “condition” would mean state, circumstance, or requirement. Although the text implies that visiting the store was helpful for acquiring information since people shared news there, it wouldn’t make sense to say that the general store was a condition of information. Choice D is incorrect because “waste” would mean something that is unused, discarded, or spent unnecessarily, which would not make sense in context. The text describes the general store as an essential part of daily life and a place for socializing and information sharing. The store was therefore a source, not a waste, of information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Jacob Lawrence’s artistic process. In this context, “observant” means watchful and perceptive. The text emphasizes that the “close attention” Lawrence paid to “all the details” of his neighborhood allowed him to reflect subtle elements of “the beauty and vitality of the Black experience” in his artwork. This context indicates that being observant of his surroundings was an important part of Lawrence’s work as an artist."}, {"type": "paragraph", "text": "Choice A is incorrect because the text gives no indication that Lawrence was “skeptical,” or had an attitude of doubt in general or about particular things, let alone that skepticism was important to him as an artist. Rather than indicating that he was skeptical, the text focuses on how Lawrence paid careful attention to everything around him and reflected his observations in his artwork. Choice C is incorrect because the text gives no indication that Lawrence was “critical,” which in this context would mean inclined to criticize harshly or unfairly. Rather than indicating that Lawrence found fault in things, the text suggests that he paid careful attention to everything around him and that his artwork reflects this careful attention. Choice D is incorrect because the text doesn’t suggest that Lawrence was “confident,” or self-assured. Rather than addressing how Lawrence felt about himself and how that feeling affected his artistic process, the text emphasizes the careful attention Lawrence paid to everything around him— attention that allowed him to capture subtle elements of a particular place and time in his artwork."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most logically completes the text’s discussion of Ochoa’s prediction that humans will one day need to live in places other than Earth. As used in this context, “speculates” would mean puts forward an idea without firm evidence. The text states that Ochoa “doesn’t have a definite idea” about when humans might need to live in other environments and characterizes Ochoa’s prediction as a “conjecture,” or a conclusion presented without convincing evidence. This context indicates that Ochoa speculates when she makes this prediction."}, {"type": "paragraph", "text": "Choice A is incorrect because saying that Ochoa “demands,” or insists or requires, that humans will one day need to live in other environments than Earth’s would not make sense in context. The text indicates that she’s unsure about the timing but hypothesizes that it will someday happen. Choice C is incorrect because saying that Ochoa “doubts,” or questions or disbelieves, that humans will one day need to live in other environments than Earth’s would not make sense in context. The text indicates that although Ochoa is unsure about the timing, she hypothesizes that humans will need to live in places other than Earth and encourages research into future travel to the moon. Choice D is incorrect because saying that Ochoa “establishes,” or proves, that humans will one day need to live in other environments than Earth’s would not make sense in context. Rather than stating that Ochoa discusses her idea with certainty and supports it with evidence, the text indicates that Ochoa is unsure about when humans might need to live in other environments."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of a relationship between the dodder plant and its host plant. As used in this context, “synchronization” means the act of things happening at the same time. The text indicates that the dodder and its host plant flower in unison and that this synchronization occurs because the dodder makes use of a protein produced by the host shortly before flowering."}, {"type": "paragraph", "text": "Choice B is incorrect because referring to “hibernation,” or the state of being dormant or inactive, wouldn’t make sense in context. The text focuses on something the dodder plant actively engages in—making use of a protein and producing flowers. Choice C is incorrect because stating that the dodder plant and its host engage together in “prediction,” or the act of declaring or indicating something in advance, wouldn’t make sense in context. Rather than indicating that the dodder plant and its host plant make a prediction about flowering activity, the text suggests that the host produces a protein as part of its regular flowering process and that the dodder then absorbs and uses that protein to flower at the same time. Choice D is incorrect because referring to “moderation,” or the act of causing something to become less intense or extreme, wouldn’t make sense in context. Although the text states that the dodder plant absorbs and uses a protein made by its host plant, it doesn’t suggest that the dodder lessens the host plant’s flowering activity; the two plants simply flower in unison."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of historical evidence about ancient Egypt under the reign of the pharaoh Hatshepsut. In this context, “an exhaustive” account would be a thorough one. The text states that much of the evidence from her reign was purposely destroyed—in other words, there is a lack of surviving records. This context conveys that unless there are major new archaeological discoveries, an exhaustive account of Hatshepsut’s reign is unlikely."}, {"type": "paragraph", "text": "Choice A is incorrect because in this context, “an imaginative” account would be an account based on imagination, or ideas and speculation, rather than facts. The text indicates that much of the evidence of Hatshepsut’s reign was deliberately destroyed, and a lack of evidence actually makes it more likely that accounts will be imaginative to some degree and not strictly factual. Choice B is incorrect because in this context, “a superficial” account would be one that is lacking in depth or concerned only with what is obvious. The text indicates that most evidence of Hatshepsut’s reign was purposely destroyed, which suggests that accounts of that time are likely already somewhat superficial, since there is little information available to support deeper knowledge. Further, it would be illogical to suggest that discovering major new evidence would make it more likely that accounts would be superficial. Choice D is incorrect because “a questionable” account would be one likely to be challenged or doubted, and since the text suggests that little evidence of Hatshepsut’s reign has survived, accounts of that time probably involve some speculation and thus may already be open to doubt. Further, it would be illogical to suggest that discovering major new evidence would make it more likely that accounts would be questionable."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it best describes the main purpose of the text. The text indicates where and when jazz tap first developed (in African American communities in the 1920s) and what influenced it (the quick rhythms and improvisations in jazz music) and then explains that it evolved alongside jazz music in the 1930s and 1940s, resulting in a very different form of tap dance than had existed before. Therefore, the main purpose of the text is to discuss jazz tap’s development."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text indicates that jazz music became widely popular in the US in the 1920s and describes some of jazz music’s qualities, the text never explains why audiences prefer some kinds of music—jazz or otherwise—over others. Choice C is incorrect because the text never mentions any musical instruments and doesn’t describe how to play one. Choice D is incorrect because the text discusses jazz tap generally and never identifies a particular dancer, famous or otherwise."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately describes the overall structure of the text. The text begins by pointing out an obstacle to observing the astronomical phenomenon of the NCP: the NCP is visible only at night. The text then indicates that, inspired by the ability of some insects and birds to navigate using visualizations of polarized sunlight, researchers devised a way to locate the NCP during daylight. The text then indicates that the researchers mimicked the insects’ and birds’ polarized-light visualization capabilities using a polarimetric camera. Thus, the text notes an obstacle to observing an astronomical phenomenon, mentions a navigational ability of certain animals that inspired a solution to that obstacle, and then explains how researchers used an optical device to mimic that ability."}, {"type": "paragraph", "text": "Choice A is incorrect. Although it’s reasonable to conjecture that humans have used the NCP for navigation, the text doesn’t indicate this is the case, let alone that the NCP is relevant to a majority of navigational tools. Furthermore, the text doesn’t state that researchers discovered that insects and birds navigate without the NCP; rather, it indicates that it’s known that some animals navigate by using skylight polarization to locate the NCP during the day and that this knowledge inspired the method the researchers devised. Choice B is incorrect. Although it’s reasonable to conjecture that humans have used the NCP for navigation, the text doesn’t state that this is the case. Furthermore, the text discusses how some animals’ use of navigational strategies based on the same celestial occurrence served as the inspiration for the researchers’ polarized-light approach, not as the basis for a comparison of the relative effectiveness of animal and human methods of navigation. Choice C is incorrect. Although the text implies that humans have typically been able to locate the NCP visually at night and indicates that some animals use the NCP to navigate, the text doesn’t state that humans use the NCP for navigation. The text therefore doesn’t emphasize a difference between how humans and animals use the NCP for this purpose. Furthermore, the text doesn’t suggest that existing navigational instruments will be augmented with polarimetric technologies."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined sentence in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately describes how the underlined sentence functions in the text as a whole. The text establishes that John has a strong imagination and then goes on to describe the St. John River near John’s home in the Florida woods. The underlined sentence depicts John sending twigs sailing down the river while he imagines them reaching “Jacksonville, the sea, the wide world,” where he wishes he could follow. This suggests that John longs to expand his life experiences beyond the Florida woods."}, {"type": "paragraph", "text": "Choice A is incorrect because the second and third sentences of the text provide an extended description of the riverbank where John likes to go, whereas the underlined sentence describes what John does at that location. Choice B is incorrect because the first sentence of the text suggests that John’s behavior “was puzzling” to others around him, whereas the underlined sentence concerns the content of John’s imaginings. Choice C is incorrect because the underlined sentence elaborates on John’s imagination but doesn’t mention any other children to whom John could be compared."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the second sentence in the overall structure of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it best describes how the second sentence functions in the text as a whole. The first sentence establishes something astronomers believe with some certainty: that Betelgeuse will explode in a supernova. The second sentence then introduces a problem: astronomers aren’t certain when Betelgeuse will explode because they don’t have enough information about the star’s internal characteristics. Finally, the third sentence indicates that researcher Sarafina El-Badry Nance and colleagues investigated a possible method of obtaining the necessary information about Betelgeuse’s internal characteristics, though they found that the method wouldn’t be sufficient. Thus, the function of the second sentence is to identify the problem that Nance and colleagues attempted to solve but didn’t."}, {"type": "paragraph", "text": "Choice A is incorrect because the second sentence introduces the general problem Nance and colleagues hoped to solve, not a serious limitation of how Nance and colleagues tried to solve it. It is the third sentence that introduces Nance and colleagues, but no serious limitation of their approach to studying a method of determining internal stellar states is described. Choice B is incorrect because the second sentence introduces the general problem Nance and colleagues hoped to solve, not the central finding they ultimately reported. It is the third sentence that presents Nance and colleagues’ conclusion that a potential method for determining internal stellar states would be insufficient."}, {"type": "paragraph", "text": "Choice D is incorrect because the second sentence doesn’t indicate how other astronomers or astrophysicists responded to the work done by Nance and colleagues; the text doesn’t address this information at all."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the texts, how would Putirka and Xu (Text 2) most likely characterize the conclusion presented in Text 1?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it reflects how Putirka and Xu (Text 2) would likely characterize the conclusion presented in Text 1. Text 1 discusses a study by Mark Holland and colleagues in which they detected traces of lithium and sodium in the atmospheres of four white dwarf stars. The team claims that this supports the idea that exoplanets with continental crusts like Earth’s once orbited these stars. Text 2 introduces Putirka and Xu, who indicate that sodium and lithium are present in several different minerals and that some of those minerals might exist in types of rock that are not found on Earth. Therefore, Putirka and Xu would likely describe the conclusion in Text 1 as questionable because it does not consider that lithium and sodium are also found in rocks that are not like Earth’s continental crust."}, {"type": "paragraph", "text": "Choice A is incorrect because the texts do not indicate how widely held any of the viewpoints described are. Choice B is incorrect because neither text discusses how new this area of study is. Choice D is incorrect because neither text discusses how likely lithium and sodium are to be detected by analyzing wavelengths of light."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, how does the narrator feel about being at summer camp?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most accurately states how the narrator feels about being at summer camp. In the text, the narrator states that after arriving at the camp, he found it to be different than he’d expected and that as a result, he felt “scared, but also excited.”"}, {"type": "paragraph", "text": "Choice A is incorrect. In the text, the narrator describes himself as “excited.” Although excitement is a positive emotion, it isn’t as intensely positive as feeling overjoyed is. Moreover, the narrator also notes that he felt “scared.” In other words, his excitement (a positive emotion) is balanced with fear (a negative emotion). Given this mixture of positive and negative emotions, it would be inaccurate to characterize the narrator as overjoyed. Choice B is incorrect because in the text, the narrator describes himself as having felt both fear and excitement. Neither of these emotions can be thought of as peaceful and, in fact, are almost the opposite of a sense of peace. Choice D is incorrect because in the text, the narrator describes himself as both “scared” and “excited,” not angry and jealous."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "According to the text, what is true about Dorian?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it presents a statement about Dorian that is directly supported by the text. The narrator of the text says that when Dorian sees his portrait, “his cheeks flushed for a moment with pleasure” and “a look of joy came into his eyes.” The narrator goes on to say that Dorian looked at the portrait “in wonder” and presents him as being so entranced by the portrait that he doesn’t notice what Hallward is saying to him. All these details support the description of Dorian as being delighted by what he sees in the portrait."}, {"type": "paragraph", "text": "Choice A is incorrect because Dorian isn’t depicted as interested in Hallward’s opinion of the portrait but rather as so enraptured by the painting that he’s hardly even aware of Hallward. Choice C is incorrect because the portrait of Dorian is the only painting that is mentioned in the text, so there’s no evidence that Dorian prefers portraits to other types of paintings. Although Dorian is depicted as delighted with this particular portrait, there’s no way of knowing from the text whether he likes portraits better than other kinds of paintings. Choice D is incorrect because nothing in the text suggests that Dorian is uncertain about Hallward’s talent. Instead, the text is focused on Dorian’s delight with the portrait."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes Gibson’s approach to art, as presented in the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most accurately describes Gibson’s approach to art. As the text explains, Gibson, who is Cherokee and Choctaw, transforms punching bags into art pieces by applying (or attaching) to them beadwork and elements of Native dressmaking, including leather fringe and the jingles of the jingle dress. The text goes on to say that in most Native communities, the art forms of beadwork and dressmaking are traditionally practiced by women. Therefore, Gibson’s approach to art consists of creating original works by drawing from traditional Native art forms."}, {"type": "paragraph", "text": "Choice B is incorrect. Because Gibson incorporates Native art forms into his own original artwork, it can be inferred that he has been influenced by other Native artists, but the text never suggests that non-Native artists have influenced him."}, {"type": "paragraph", "text": "Choice C is incorrect because the text doesn’t indicate that Gibson designs dresses influenced by boxing but instead that he turns punching bags, which are used in boxing, into works of art by applying elements of Native dressmaking to them. Choice D is incorrect. Although Gibson does incorporate beadwork into his art, the text never mentions the colors or patterns that he uses or suggests that his art defies the expectations that people might have about color and pattern in beadwork."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which quotation from O Pioneers! most effectively illustrates the claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the quotation that most directly illustrates the claim that Cather portrays Alexandra as having a deep emotional connection to her natural surroundings. This quotation states that the country meant a great deal to Alexandra and then goes on to detail several ways in which her natural surroundings affect her emotionally: the insects sound like “the sweetest music,” she feels as though “her heart were hiding” in the grass “with the quail and the plover,” and near the ridges she feels “the future stirring.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the quotation doesn’t suggest that Alexandra had a deep emotional connection to her natural surroundings but instead describes how she interacts with the people around her to learn more about crops, poultry, and experiments with clover hay. Choice C is incorrect because the quotation doesn’t suggest that Alexandra has a deep emotional connection to her natural surroundings but instead describes her nighttime departure in a wagon. The quotation says nothing about Alexandra’s emotional state. Choice D is incorrect because the quotation doesn’t convey Alexandra’s deep emotional connection to her natural surroundings; instead, this quotation describes how well she understands the markets and livestock."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most strongly support the scholar’s claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a finding that, if true, would support the scholar’s claim about Toni Morrison’s likely goal of strengthening the presence of Black writers on Random House’s list of published authors. The text explains that Morrison was the first Black woman to be an editor for Random House and that she was an editor there from 1967 to 1983. If it were true that Random House published a higher percentage of works by Black authors throughout the 1970s—during most of Morrison’s time working there—than it had previously published, that would suggest that Morrison may have made a deliberate effort to strengthen the presence of Black authors on the list of Random House’s published authors, thus supporting the scholar’s claim."}, {"type": "paragraph", "text": "Choice B is incorrect because the scholar’s claim is about Morrison’s work as an editor at a publishing company and her likely effort to strengthen the presence of Black writers on that company’s list of published authors. It might be true that Black authors interviewed in the 1980s and 1990s often cited Morrison’s novels as an influence on their work, but that finding would simply suggest something about how those authors approached their work; it wouldn’t show that Morrison intended to increase the number of Black writers among the published authors specifically at Random House. Choice C is incorrect because the scholar’s claim is about Morrison’s work as an editor at a publishing company, not about her work as a novelist. Therefore, a finding that Morrison’s novels published after 1983 sold more copies and were more widely acclaimed than her earlier novels would have no bearing on the claim that as an editor Morrison made an effort to ensure that more Black writers were present on Random House’s list of published authors."}, {"type": "paragraph", "text": "Choice D is incorrect. Although the text discusses Morrison’s work as an editor at Random House, the scholar’s claim focuses on Morrison’s likely effort in that role to increase the number of Black writers present on Random House’s list of published authors, not on the influence she may have had on the content of the works she edited. Without knowing whether Morrison’s stylistic influence led to more publications or if Morrison applied her influence specifically to works by Black writers, the finding that works edited by Morrison could be identified by stylistic characteristics would have no bearing on the claim that Morrison intended to strengthen the presence of Black writers among the published authors at Random House."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most strongly support the team’s conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents a finding that, if true, would most strongly support the team’s conclusion that cattle were likely raised closer to human settlements than sheep and goats were. The text explains that Vaiglova, Liu, and their colleagues analyzed the chemical composition of sheep, goat, and cattle bones from the Bronze Age in China in order to investigate the animals’ domestication, or their adaptation from a wild state to a state in which they existed in close connection with humans. According to the text, the team’s analysis showed that sheep and goats of the era fed largely on wild plants, whereas cattle fed on millet—importantly, a crop cultivated by humans. If analysis of the animal bones shows that the cattle’s diet also consisted of wheat, another crop cultivated by humans in China during the Bronze Age, the finding would support the team’s conclusion by offering additional evidence that cattle during this era fed on human-grown crops—and, by extension, that humans raised cattle relatively close to the settlements where they grew these crops, leaving goats and sheep to roam farther away in areas with wild vegetation, uncultivated by humans."}, {"type": "paragraph", "text": "Choice B is incorrect because if it were true that sheep’s and goats’ diets consisted of small portions of millet, which the text states was a crop cultivated by humans, the finding would suggest that sheep and goats were raised relatively close to human settlements, weakening the team’s conclusion that cattle were likely raised closer to those settlements than sheep and goats were. Choice C is incorrect because the finding that cattle generally require more food and nutrients than do sheep and goats wouldn’t support the team’s conclusion that cattle were likely raised closer to human settlements than sheep and goats were. Nothing in the text suggests that cattle were incapable of obtaining sufficient food and nutrients without access to human-grown crops. Hence, even if cattle’s diets are found to have different requirements than the diets of sheep and goats, the cattle could have met those requirements from food located far from human settlements. Choice D is incorrect because if it were true that the diets of sheep, goats, and cattle varied based on what the farmers in each Bronze Age settlement could grow, the finding would weaken the team’s conclusion that cattle were likely raised closer to human settlements than sheep and goats were, suggesting instead that all three types of animals were raised close enough to human settlements to feed on those settlements’ crops."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which completion of the text is best supported by data in the graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text based on supporting data in the graph. The text indicates that in the fly D. melanogaster, DptA and DptB are genes that encode peptides that both fight pathogens and promote beneficial microbes. Researchers tested D. melanogaster’s resistance to P. rettgeri and A. sicerae bacteria based on which variation of the peptide- encoding gene the flies exhibit: DptA silenced (referred to as type A), DptB silenced (type B), or both silenced (type AB). The text also indicates that resistance to P. rettgeri correlates with DptA activity but not with DptB activity (which would manifest as type B flies surviving at a higher rate than other fly types when exposed to P. rettgeri). The graph shows the post–A. sicerae infection results, which indicate that DptB activity was most strongly associated with survival, whereas DptA activity was not (manifesting in the graph as the type A flies having greater survival rates than the other fly types). In other words, when DptA activity was silenced, the flies showed relatively high survival rates, but when DptB activity was silenced, whether on its own or in conjunction with DptA activity being silenced, survival rates were low, suggesting that DptB may have developed as a specific defense against A. sicerae."}, {"type": "paragraph", "text": "Choice A is incorrect. The graph suggests that DptA activity is associated with a low rate of survival, not a high one. Furthermore, the graph shows results for flies where DptA alone was silenced, DptB alone was silenced, and both were silenced and thus does not show any flies with activity in both DptA and DptB, which would be necessary to determine whether DptA conferred defense against A. sicerae in the presence of DptB. Choice B is incorrect. Only two bacteria species were considered in the text: P. rettgeri and A. sicerae. The text and graph taken together suggest that activity in DptA is associated with resistance to P. rettgeri while DptB activity is not, and that DptB activity is associated with resistance to A. sicerae while DptA is not. There is no further information to suggest one genetic type confers resistance to a greater number of pathogens than the other."}, {"type": "paragraph", "text": "Choice D is incorrect. The graph does not address flies with activity in both DptA and DptB. All flies represented in the graph had one or both of DptA and DptB silenced, or inactive."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents the conclusion that most logically follows from the text’s discussion of leafy spurge and engineered DNA. The text establishes that using chemical herbicides to control leafy spurge in North America can also harm other plants nearby. The text then indicates that it might be possible to use engineered DNA to prevent plants from reproducing, which would be useful for “exclusively targeting” leafy spurge. If it’s possible to exclusively target leafy spurge with engineered DNA—meaning that only leafy spurge is affected by the engineered DNA—and prevent the plant from reproducing, then leafy spurge numbers could be reduced “without harming other organisms.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the text raises the possibility of using engineered DNA to prevent leafy spurge from reproducing, not to make individual leafy spurge plants more vulnerable to chemical herbicides that already exist. Choice B is incorrect because the text doesn’t describe any ecological benefits of leafy spurge in North America; instead, the text is focused on using engineered DNA to prevent leafy spurge from reproducing and thereby reduce its numbers. The only ecological effects of leafy spurge in North America that are described in the text are harmful. Choice C is incorrect because the text describes the possibility of using engineered DNA to prevent leafy spurge from reproducing; it doesn’t offer a way to enable cattle to eat leafy spurge without becoming sick."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer because it most logically completes the text’s discussion of accelerated flowering in A. thaliana plants. The text indicates that A. thaliana plants show accelerated flowering at high temperatures. To investigate the mechanism for this accelerated flowering, biologists replaced the ELF3 protein in one group of A. thaliana plants with a similar protein found in another plant species that doesn’t show accelerated flowering. The team then compared these modified plants to A. thaliana plants that retained their original ELF3 protein. The text states that the two samples of plants showed no difference in flowering at 22° Celsius, but at 27° Celsius the unaltered plants with ELF3 showed accelerated flowering while the plants without ELF3 didn’t. If accelerated flowering at the higher temperature occurred in the A. thaliana plants with ELF3 but not in the plants without the protein, then ELF3 likely enables A. thaliana to respond to increased temperatures."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t mention whether any plants other than A. thaliana and stiff brome show temperature-sensitive flowering, so there is no support for the idea that this type of flowering is unique to A. thaliana. Choice B is incorrect because the text discusses the effects of ELF3 and not the production of it. There’s nothing in the text to suggest that the amount of ELF3 in A. thaliana varies with temperature. Choice D is incorrect. While the text states that there was no difference in the flowering of modified and unmodified A. thaliana plants at 22° Celsius, there’s no suggestion that A. thaliana only begins to flower at 22° Celsius; the text doesn’t mention a specific temperature threshold required for A. thaliana flowering."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the coordination of main clauses within a sentence. This choice correctly uses a comma and the coordinating conjunction “but” to join the first main clause (“the Alvarez…out”) and the second main clause (“it left…extinctions”)."}, {"type": "paragraph", "text": "Choice A is incorrect because when coordinating two longer main clauses such as these, it’s conventional to use a comma before the coordinating conjunction."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in a run-on sentence. The two main clauses are fused without punctuation and/or a conjunction. Choice D is incorrect because it results in a comma splice. Without a conjunction following it, a comma can’t be used in this way to join two main clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the coordination of independent clauses within a sentence. An independent clause is a phrase containing a subject and a verb that can stand on its own as a sentence. This choice uses a comma and the coordinating conjunction “but” to join the first independent clause (“underlines…lower a book’s value”) and the second independent clause (“such markings…can be a gold mine to scholars”) to create a compound sentence."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a run-on sentence. The two independent clauses are fused without punctuation and/or a conjunction."}, {"type": "paragraph", "text": "Choice C is incorrect because it results in a comma splice. A comma can’t be used in this way to mark the boundary between two independent clauses. Choice D is incorrect because a comma is needed to mark the boundary between two coordinated independent clauses."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of finite and nonfinite verb forms within a sentence. The nonfinite present participle “forcing” is correctly used to form a participial phrase that supplements the main clause “those...cover,” describing the effects on monkeys of the lack of food sources."}, {"type": "paragraph", "text": "Choice A is incorrect because the finite present tense verb “forces” can’t be used in this way to supplement the main clause (“those...cover”). Choice B is incorrect. While the nonfinite to-infinitive “to force” could be used to form a subordinate clause that supplements the main clause (“those...cover”), to-infinitives conventionally express purpose, and nothing in the sentence suggests that the food sources become unavailable for the purpose of forcing monkeys to hunt marine animals. Choice D is incorrect because the finite past tense verb “forced” can’t be used in this way to supplement the main clause (“those...cover”)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is punctuation between a subordinate clause and a main clause. This choice correctly uses a comma to mark the boundary between the subordinate clause (“While…lifelike”) and the main clause (“others look to the past”)."}, {"type": "paragraph", "text": "Choice A is incorrect because it results in an incomplete sentence with no main clause. Choice B is incorrect because it fails to mark the boundary between the subordinate clause (“While…lifelike”) and the main clause (“others…past”)."}, {"type": "paragraph", "text": "Choice D is incorrect because it results in an incomplete sentence with no main clause."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb “experiences” is consistent with the other present tense verbs (e.g., “connects” and “prepares”) used to describe the events in Truong’s novels. Furthermore, it’s conventional to use the present tense when discussing a literary work."}, {"type": "paragraph", "text": "Choice A is incorrect because the past tense verb “experienced” isn’t consistent with the other present tense verbs used to describe the events in Truong’s novels."}, {"type": "paragraph", "text": "Choice B is incorrect because the past perfect tense verb “had experienced” isn’t consistent with the other present tense verbs used to describe the events in Truong’s novels. Choice D is incorrect because the future progressive tense verb “will be experiencing” isn’t consistent with the other present tense verbs used to describe the events in Truong’s novels."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of punctuation in a sentence. In this choice, a colon is correctly used to mark the boundary between one main clause (“Along with...photosynthesis”) and another main clause (“as light...oxygen”) and to introduce the following explanation of how light intensity affects photosynthesis."}, {"type": "paragraph", "text": "Choice A is incorrect because when coordinating two longer main clauses such as these, it’s conventional to use a comma before the coordinating conjunction (“and”). Choice B is incorrect because it results in a comma splice. Without a coordinating conjunction following it, a comma can’t be used in this way to join two main clauses (“Along with...photosynthesis” and “as light...oxygen”). Choice D is incorrect because it results in a run-on sentence. The two main clauses (“Along with...photosynthesis” and “as light...oxygen”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is the use of possessive determiners. The plural possessive determiner “their” agrees in number with the plural noun “types” and thus indicates that the more personal subject matter of Marisol’s 1968 sculpture takes the place of those types of pop culture references that made Marisol a star."}, {"type": "paragraph", "text": "Choice A is incorrect because the singular possessive determiner “its” doesn’t agree in number with the plural noun “types.” Choice B is incorrect because “they’re” is the contraction for “they are,” not a possessive determiner. Choice D is incorrect because “it’s” is the contraction for “it is” or “it has,” not a possessive determiner."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. The singular verb “is” agrees in number with the singular subject “each one of a ghazal’s couplets.” While the prepositional phrase “of a ghazal’s couplets” within the subject contains a plural noun, the head of the subject (“each one”) is singular, indicating that each individual couplet (not the couplets as a group) is “thematically and logically autonomous,” or self-standing."}, {"type": "paragraph", "text": "Choice B is incorrect because the plural verb “were” doesn’t agree in number with the singular subject “each one of a ghazal’s couplets.” Choice C is incorrect because the plural verb “have been” doesn’t agree in number with the singular subject “each one of a ghazal’s couplets.” Choice D is incorrect because the plural verb “are” doesn’t agree in number with the singular subject “each one of a ghazal’s couplets.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “For example” logically signals that the information in this sentence—that tadpole shrimp embryos can pause development during extended periods of drought— exemplifies the previous sentence’s claim that organisms have evolved surprising adaptations to survive in adverse conditions."}, {"type": "paragraph", "text": "Choice A is incorrect because “in contrast” illogically signals that the information in this sentence contrasts with the claim about organisms in the previous sentence. Instead, it exemplifies this claim. Choice C is incorrect because “meanwhile” illogically signals that the information in this sentence is separate from (while occurring simultaneously with) the claim about organisms in the previous sentence. Instead, it exemplifies this claim. Choice D is incorrect because “consequently” illogically signals that the information in this sentence is a consequence, or result, of the claim about organisms in the previous sentence. Instead, it exemplifies this claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Previously” logically signals that the event described in this sentence—Bigelow being named best director—occurred before Zhao’s win. The fact that only one other woman had won the award before puts Zhao’s win in perspective."}, {"type": "paragraph", "text": "Choice A is incorrect because “as a result” illogically signals that the event described in this sentence occurred as a result or consequence of Zhao’s win. Instead, it occurred before Zhao was named best director and puts Zhao’s win in perspective. Choice C is incorrect because “however” illogically signals that the event described in this sentence occurred in spite of or in contrast to Zhao’s win. Instead, it occurred before Zhao was named best director and puts Zhao’s win in perspective. Choice D is incorrect because “likewise” illogically signals that this sentence merely adds a second, similar piece of information to the information about Zhao’s win. Instead, the fact that only one other woman had won the award before puts Zhao’s win in perspective."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Hence” correctly signals that the claim in this sentence regarding extraterrestrial material follows logically from the information in the previous sentences. The previous sentences establish that siderophile elements in the mantle are more abundant than predicted in the core- differentiation model. This sentence claims, logically, that these elements came from extraterrestrial material that accreted to Earth after core differentiation."}, {"type": "paragraph", "text": "Choice A is incorrect because “that said” illogically signals that the information in this sentence regarding extraterrestrial material is an exception to the previous information about siderophiles’ abundance in the mantle. Instead, it is a new claim that follows logically from the previous information. Choice C is incorrect because “for example” illogically signals that the information in this sentence regarding extraterrestrial material exemplifies the previous information about siderophiles’ abundance in the mantle. Instead, it is a new claim that follows logically from the previous information. Choice D is incorrect because “likewise” illogically signals that the information in this sentence regarding extraterrestrial material is merely similar to the previous information about siderophiles’ abundance in the mantle. Instead, it is a new claim that follows logically from the previous information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The sentence presents the study, describing it as a 2013 analysis of Quanhucun cat bone fragments, and its conclusions, indicating what the analysis suggests about cat domestication in Quanhucun."}, {"type": "paragraph", "text": "Choice A is incorrect because the sentence focuses on the study’s methodology; it doesn’t present conclusions from the study. Choice C is incorrect. While the sentence provides a general overview of the study, it doesn’t present conclusions from the study. Choice D is incorrect. The sentence describes a finding from the study; it doesn’t present conclusions from the study."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes a difference between the portraits, noting that one is a painting and the other is a drawing."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence emphasizes a similarity between the two portraits rather than a difference. Choice B is incorrect. The sentence makes a generalization about Enriquez’s portraits; it doesn’t emphasize a difference between the portraits of Jimenez and Anaya. Choice D is incorrect. While the sentence notes a difference between Jimenez and Anaya, it doesn’t emphasize a difference between, or even mention, their portraits."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes both the duration (the length of time) and the purpose of Cohen’s and Rodrigues’s work by noting that the women have been working since 2003 to preserve Gullah culture."}, {"type": "paragraph", "text": "Choice A is incorrect. While the sentence emphasizes what visitors to Cohen’s and Rodrigues’s museums can learn, it doesn’t mention the duration or purpose of the women’s work. Choice B is incorrect. While the sentence emphasizes the purpose of Cohen’s and Rodrigues’s work, it doesn’t mention the duration of that work (the length of time the women have been working to preserve Gullah culture)."}, {"type": "paragraph", "text": "Choice D is incorrect. While the sentence emphasizes where and when Gullah culture developed, it doesn’t mention the duration or purpose of Cohen’s and Rodrigues’s work."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the writing system created by Sequoyah. In this context, “widespread” means widely accepted or practiced. The text indicates that because Sequoyah’s script accurately represented the spoken sounds of the Cherokee language and was easy to learn, nearly all Cherokee people were able to read and write it soon after it was created. This context demonstrates that the script was widely used by the Cherokee people."}, {"type": "paragraph", "text": "Choice B is incorrect. In this context, “careful” would mean exercised with care and attentive concern. Although the work of creating a writing system likely involved great care, the text indicates that the system was “easy to learn,” which conflicts with the idea that using this system requires a noteworthy amount of care. Choice C is incorrect because in this context “unintended” means not deliberate. The idea that using Sequoyah’s script was unintentional conflicts directly with the claim that it was easy to learn and used by “over 90% of the Cherokee people” by 1830. In fact, because one had to learn this system, it’s not clear how one could use it unintentionally. Choice D is incorrect because in this context “infrequent” means rare or not occurring often, which conflicts directly with the claim that “over 90% of the Cherokee people” were using Sequoyah’s script by 1830."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of diaphragm contractions and hiccups. In this context, “involuntarily” means done without any control, or by reflex. The text explains that when a person’s diaphragm contracts and results in hiccups (which may be important for infants), those muscle contractions are “uncontrollable.” This context indicates that the diaphragm contractions occur without the person’s control."}, {"type": "paragraph", "text": "Choice B is incorrect because the text indicates that researchers haven’t determined exactly why people hiccup, suggesting that it isn’t known that the uncontrollable muscle contractions generally occur “beneficially,” or with a good or helpful effect—even if one neuroscientist has found that it’s possible hiccups play an important positive role for a specific group of people (infants). Choice C is incorrect because the text describes the diaphragm contractions that result in hiccups as “uncontrollable,” or happening without the person’s control, so it wouldn’t make sense to describe them as occurring “strenuously,” or in a way that requires great effort or energy. Choice D is incorrect because nothing in the text indicates that the diaphragm contractions resulting in hiccups occur “smoothly,” or evenly and continuously. The text doesn’t describe the quality of the muscle contractions beyond stating that they are “uncontrollable.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most logically completes the text’s discussion of the location of the province of Xoconochco within the Aztec Empire. As used in this context, “peripheral” means situated toward the outer bounds rather than the center. The text indicates that Xoconochco was located on a coast, hundreds of kilometers away from the capital of the Aztec Empire. The text also states that trade between the province and the capital required “a long overland journey.” This context suggests that Xoconochco was situated toward an edge of the empire’s territory rather than near its center."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t make sense in context to refer to Xoconochco’s location within the Aztec Empire as “unobtrusive,” or not blatant or undesirably prominent; it’s not clear how a province’s physical location would or wouldn’t be blatant. Instead of focusing on how noticeable Xoconochco’s location was, the text emphasizes the province’s distance from the capital of the empire, pointing out that because of this distance trade between the two required “a long overland journey.” Choice B is incorrect because the text indicates that the province of Xoconochco was located on a coast far from the capital of the Aztec Empire, not that it was “concealed,” or kept out of sight or hidden from view. Nothing in the text suggests that Xoconochco was actually hidden such that people couldn’t see it, and being hidden wouldn’t necessarily result in trade between the province and the capital requiring “a long overland journey.” Choice C is incorrect because to say that Xoconochco’s location within the Aztec Empire was “approximate” would mean that the location either wasn’t precisely correct or was close to some other location. Neither of these meanings would make sense in context because the text indicates that Xoconochco’s location is known and that it was far from the empire’s capital, so there’s no reason to characterize the location as either not precisely correct or close to another location."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the consequences of raising the age at which retirees begin receiving government funds. The text indicates that raising the age for these funds is usually discussed in terms of effects on fund recipients but that Andria Smythe is instead considering the effects on working family members who care for retirees. Smythe notes that raising the age for the funds would increase the length of time retirees are dependent on financial assistance from working family members. This is suggested to have an effect on wealth creation for those workers, and most logically, that effect would be disadvantageous. Thus, “stymie,” which means to prevent or greatly hinder, is the most logical choice in context."}, {"type": "paragraph", "text": "Choice B is incorrect because in this context, “compound” would most nearly mean multiply or greatly enhance. The text indicates that raising the age at which retirees are eligible for government funds will increase the amount of time retirees are dependent on working family members for financial support. This would likely have a negative rather than a positive effect on wealth creation. Choice C is incorrect because in this context, “disparage” would most nearly mean criticize or defame. Nothing in the text suggests that raising the age at which retirees are eligible for government funds would defame wealth creation among working adults. Choice D is incorrect because in this context, “outstrip” would most nearly mean to exceed, and nothing in the text indicates that the financial support provided to retirees would exceed the amount of wealth these workers can create. The text does suggest that workers providing funds to retirees works against those workers’ wealth accumulation, but not that the support to retirees exceeds the workers’ accumulated wealth."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical and precise word or phrase?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of political blogs. In this context, “sanguine” means optimistic. The text begins by noting the rise of political blogs with readily identifiable ideological alignments in the early 2000s. The text then indicates that some commentators saw this as a positive development, citing a reason why (their difference from traditional news). Finally, the text goes on to contrast those commentators with others who have a negative opinion of the rise of political blogs (because they increase political polarization among their readers). This context supports the idea that the second group of commentators is less positive than the first: thus, the second group of commentators is less optimistic, or sanguine."}, {"type": "paragraph", "text": "Choice B is incorrect because it would not make sense in this context to describe those commentators who have a negative opinion of political blogs as less “recalcitrant,” or obstinately uncooperative, than those commentators who supported political blogs. Choice C is incorrect because the text gives no indication that those commentators who have a negative opinion of political blogs are less “misanthropic,” or less contemptuous of humankind, than those commentators who have a positive opinion of political blogs— there is no indication in the text that those commentators who like political blogs would be contemptuous of humankind at all. Choice D is incorrect because there is no evidence that those commentators who have a negative opinion of political blogs are less “earnest,” or sincere, than those who have a positive opinion of such blogs—presumably, both groups of commentators hold their beliefs with equal conviction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the overall purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately describes the overall purpose of the text. The text indicates that “for as long as he could remember,” Max had “begged” his father to take him to La Reina. This point is later emphasized in the text by indicating that “this summer” his father might “finally take” Max to visit La Reina. Thus, the purpose of the text as a whole is to show how much Max wants to visit La Reina."}, {"type": "paragraph", "text": "Choice A is incorrect. The text does not discuss Papa’s feelings toward Max. Rather, it mentions that Max has long wanted Papa to take him to La Reina and that, unlike Max and some other children, Papa does not believe that La Reina is haunted. Choice B is incorrect. The text mentions that Max is “almost twelve” at the time, which suggests anticipation of growing up rather than refusal to."}, {"type": "paragraph", "text": "Choice C is incorrect. The text indicates that Max hopes to visit La Reina during the current summer, but nothing suggests that Max dislikes summer."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 6, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main purpose of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately states the main purpose of the text, which is to show that Henry’s mother, Mrs. Higgins, wants Henry to leave her house. In the text, Mrs. Higgins complains that Henry offends all her friends and that they stop coming when he’s also visiting. She then tells him directly, “you mustn’t stay.” The overall exchange conveys Mrs. Higgins’s intention for Henry to leave so as not to drive away her friends with his behavior."}, {"type": "paragraph", "text": "Choice A is incorrect because the text doesn’t indicate what Henry’s mother does when she’s out with her friends. Instead, it focuses on what goes on when Henry and her friends visit her at the same time, indicating that since her friends find Henry’s company disagreeable, she wishes him to leave before they arrive."}, {"type": "paragraph", "text": "Choice C is incorrect because the text doesn’t contain an account of what Henry’s home looks like. The setting is established as the house of Henry’s mother, and the dialogue focuses solely on her wish that Henry should depart before her friends arrive. Choice D is incorrect because the text doesn’t mention how often Henry visits his mother nor does it provide any explanation for why he visits his mother. Instead, it indicates that she thinks her friends dislike Henry and that she therefore wants him to depart before they arrive."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 7, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, 0, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes the function of the underlined portion in the text as a whole?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The text presents the speaker’s experience of viewing the sea. In the underlined portion, the speaker focuses on the idea that the waves hitting rocks on the shore are a relentless and enduring force: they are constantly pushed back (“ever repulsed”) but always return (“ever rushing on”), as though they have an energy that can’t be overcome (“a life that will not know defeat”)."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the underlined portion characterizes the waves as a relentless force (always “repulsed” but still “rushing on” and never being defeated), the speaker doesn’t suggest that the surroundings are intimidating. Instead, the speaker presents the scene in a positive way, describing the “deep delight” of the “gladsome,” or cheerful, waves and feeling “the heart / Leap joyous” while viewing the sea. Choice C is incorrect because the underlined portion doesn’t suggest that the speaker is ambivalent, or has mixed feelings about, the natural world. Instead, it presents a single view of one part of the immediate surroundings: the speaker characterizes the sea’s waves as an unstoppable force, since they are constantly pushed back but always return (“ever repulsed, yet ever rushing on”). Choice D is incorrect. Although the text later suggests the speaker’s view of her own thoughts by referring to a “clouded brain” and a heart that leaps joyously, this reference neither occurs within the underlined portion nor establishes a clear contrast with the relentless determination of the waves. The underlined portion addresses only the speaker’s view of the waves and doesn’t suggest what her own thoughts might be."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Craft and Structure'), 'medium', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best states the main idea of the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it most accurately states the main idea of the text. According to the text, conceptual artists Gins and Arakawa have designed an apartment building that is disorienting because of several unconventional elements, such as uneven kitchen counters and “a door to nowhere.” The text goes on to suggest that there may be benefits to this kind of design because filmmaker Yamaoka lived in the apartment building for four years and reported health benefits. Thus, although the design is impractical, it may improve the well-being of the apartment building’s residents."}, {"type": "paragraph", "text": "Choice A is incorrect. Although the text mentions that Yamaoka lived in the apartment for four years, it doesn’t address how long someone can beneficially live in a home surrounded by fanciful features or whether doing so can be sustained. Choice B is incorrect. Although the text mentions the potential benefits of living in a home with disorienting design features, it doesn’t suggest that this is the most effective method to create a physically stimulating environment."}, {"type": "paragraph", "text": "Choice C is incorrect because the text refers to Yamaoka to support the claim that Gins and Arakawa’s apartment building design may be beneficial, but the text doesn’t indicate that Yamaoka supports the designs of other conceptual artists."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Based on the text, how does the Lord Chancellor respond to the crowd?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a statement about how the Lord Chancellor responds to the crowd that is supported by the text. The text indicates that the people in the crowd are roaring and shouting “Bread!” or “Taxes!” and presents them as not knowing what they really want. The Lord Chancellor’s response is to ask what their shouting means but also to observe that they’re shouting with “unanimity,” or total agreement. Clearly, this isn’t the case, which supports the statement that the Lord Chancellor describes the crowd as being united even though it’s not."}, {"type": "paragraph", "text": "Choice A is incorrect because it isn’t supported by the text. Although the text indicates that the Lord Chancellor asks about the meaning of the crowd’s shouting, it doesn’t suggest that he knows what the crowd really wants. Choice B is incorrect because the text doesn’t suggest that the Lord Chancellor wants to speak to the crowd. Furthermore, the text doesn’t indicate that the crowd wants to hear from the Sub-Warden. Although the crowd roars when asked “Who roar for the Sub-Warden?” it’s unclear what the roaring means. Choice C is incorrect because the text doesn’t suggest that the Lord Chancellor knows of or sympathizes with the crowd’s demands. In addition, the text doesn’t indicate that the crowd’s shouting annoys the Lord Chancellor, just that it causes him to keep repeating “What can it all mean?”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the graph to complete the sentence?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it accurately identifies the species with the highest global biomass, the white-tailed deer at approximately 2.7 million metric tons. The graph shows the global biomass for four wild land mammal species with the highest global biomass. The graph indicates that the African bush elephant’s global biomass is about 1.3 million metric tons, the eastern gray kangaroo’s is about 0.6 million metric tons, and the wild boar’s is about 1.9 million metric tons. These values are all lower than the global biomass for the white-tailed deer’s approximately 2.7 million metric tons. Thus, the white-tailed deer is the species with the highest global biomass."}, {"type": "paragraph", "text": "Choice A is incorrect because although the graph indicates that the wild boar has a relatively high global biomass of about 1.9 million metric tons, it is not the species with the highest value. The white-tailed deer is the species with the highest global biomass at about 2.7 million metric tons. Choice B is incorrect because the eastern gray kangaroo has the lowest global biomass value shown on the graph at about 0.6 million metric tons, not the highest global biomass. The white-tailed deer has the highest at about 2.7 million metric tons. Choice C is incorrect because although the African bush elephant has a substantial global biomass of about 1.3 million metric tons, it is not the species with the highest value according to the graph. The white-tailed deer has the highest global biomass at about 2.7 million metric tons."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to support the research team’s conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most effectively uses data from the table to support the researchers’ conclusion about the harvesting of clamshells by Neanderthals for use as tools. The text explains that Neanderthals used clamshells to make tools and that the sturdiest, and therefore the most desirable, shells for this purpose are found on the seafloor, not on the beach. However, the researchers also concluded that the clamshell tools made from shells from the seafloor are rarer than those made from shells from the beach. Meanwhile the table shows that at each depth, the number of tools made from shells from the beach exceeds the number made from the more desirable shells from the seafloor. The fact that the more desirable shells are less common suggests that it was significantly more difficult to harvest shells from the seafloor than from the beach."}, {"type": "paragraph", "text": "Choice B is incorrect because knowing which depth represents the period of time with the highest Neanderthal population does not help answer the question of why the Neanderthals consistently made more tools from the less desirable shells from the beach than they made from the more desirable shells from the seafloor."}, {"type": "paragraph", "text": "Choice C is incorrect because it claims that the beach shells are more durable than the seafloor shells, which contradicts the text’s description of shells from the seafloor as smoother and sturdier than shells from the beach. Choice D is incorrect because knowing which depth has the most artifacts or whether the clam population fluctuated does not help explain why tools made from the less desirable shells from the beach outnumber tools made from the more desirable shells from the seafloor."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice best describes data from the graph that support Taylor and colleagues’ conclusion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer because it describes data from the graph that support Taylor and colleagues’ conclusion that spray coating holds promise for improving the power conversion efficiency of ETLs in perovskite solar cells. The text explains that perovskite solar cells’ efficiency at converting light into electricity is diminished by their electron transport layer (ETL), which is applied through spin coating, but that Taylor’s team devised a new spray coating method for applying the ETL that improves its power conversion efficiency. The graph displays data on the power conversion efficiency of solar cells in tests conducted by Taylor’s team, with bars for both the highest- and lowest-performing ETLs in two data categories: spray coating and spin coating. According to the graph, the lowest-performing ETL applied through spray coating had a power conversion efficiency of between 14% and 16%, while the highest-performing ETL applied through spin coating had a power conversion efficiency of less than 14%. These data confirm that ETLs applied through novel spray coating are more efficient than those applied though traditional spin coating. Thus, the data support Taylor and colleagues’ conclusion about spray coating’s potential value."}, {"type": "paragraph", "text": "Choice A is incorrect. Although this claim correctly describes the data in the graph by stating that both the lowest-performing ETL applied through spin coating and the lowest- performing ETL applied through spray coating had a power conversion efficiency greater than 10%, this relationship in the data doesn’t support or relate to Taylor and colleagues’ conclusion that spray coating promises greater efficiency for solar cells than traditional spin coating does."}, {"type": "paragraph", "text": "Choice C is incorrect. This claim does address the greater power conversion efficiency of the highest-performing ETL applied through spray coating, compared with the highest-performing ETL applied through spin coating. However, it also incorrectly cites the value for the efficiency of the highest- performing ETL applied through spray coating as approximately 13%, instead of a value between 14% and 16%, and the value for the efficiency of the highest- performing ETL applied through spin coating as approximately 11%, instead of a value between 12% and 14%, as shown in the graph. Choice D is incorrect because Taylor and colleagues’ conclusion is based on the difference in the power conversion efficiency of ETLs applied through spray coating and that of ETLs applied through spin coating, not on the difference between the highest- and lowest-performing ETLs applied through just spray coating."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 13, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses data from the table to complete the statement?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents data from the table that most effectively complete the statement about the rates at which employment shifted in France and the United States. The text states that over the last two hundred years employment in the agricultural sector has declined while employment in the service sector has risen in both France and the US, and the data from the table reflect these trends. The text asserts, however, that the transition from agriculture to services “happened at very different rates in the two countries.” This assertion is best supported by a comparison of data from 1900 and 1950: the table shows that in those years, employment in agriculture went from 43% to 32% in France (a decline of 11 percentage points) and from 41% to 14% in the US (a decline of 27 percentage points), and that employment in services went from 28% to 35% in France (an increase of 7 percentage points) and from 31% to 53% in the US (an increase of 22 percentage points). In other words, the rate of change was greater in the US than in France for both sectors."}, {"type": "paragraph", "text": "Choice B is incorrect because comparing the data for 1800 and 2012 would suggest a similar rate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 3% in 2012 in France, which is close to the change from 68% in 1800 to 2% in 2012 in the US, while employment in services went from 14% in 1800 to 76% in 2012 in France, which is close to the change from 13% in 1800 to 80% in 2012 in the US. Choice C is incorrect because comparing the data for 1900 and 2012 would suggest a similar rate of change in the two countries rather than very different rates: employment in agriculture went from 43% in 1900 to 3% in 2012 in France, which is close to the change from 41% in 1900 to 2% in 2012 in the US, while employment in services went from 28% in 1900 to 76% in 2012 in France, which is close to the change from 31% in 1900 to 80% in 2012 in the US. Choice D is incorrect because comparing the data for 1800 and 1900 would suggest a similar rate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 43% in 1900 in France, which is fairly close to the change from 68% in 1800 to 41% in 1900 in the US, while employment in services went from 14% in 1800 to 28% in 1900 in France, which is close to the change from 13% in 1800 to 31% in 1900 in the US."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 14, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which finding, if true, would most directly support Shcherbakova and colleagues’ claim?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer because it presents a finding that, if true, would support Shcherbakova and colleagues’ claim that the outcome of their study is inconsistent with the linguistic niche hypothesis (LNH). The text explains that the LNH holds that there is an inverse relationship between the prevalence of non- native speakers of a language (exotericity) and the grammatical complexity of that language—that is, that as the number of non-native speakers increases, grammatical complexity decreases, and vice versa. According to the text, Shcherbakova and colleagues focused on two positive indications of grammatical complexity—fusion and informativity—and analyzed their occurrence in over 1,300 languages. If the researchers found a slightly positive correlation between fusion and exotericity and between informativity and exotericity—meaning that to some extent, grammatical complexity increases as the number of non-native speakers of a language increases—their outcome would not be consistent with the assumption that exotericity and grammatical complexity are inversely related (the LNH)."}, {"type": "paragraph", "text": "Choice A is incorrect because it wouldn’t be possible to say that a finding of a slightly negative correlation between grammatical complexity and both fusion and informativity is inconsistent or consistent with the LNH, since the finding would address only grammatical complexity (given that fusion and informativity are aspects of grammatical complexity) and wouldn’t move beyond that factor to address its relationship to the prevalence of non-native speakers of a language (exotericity), which is the relationship the LNH focuses on. Choice B is incorrect because a finding of a slightly negative correlation between grammatical complexity and the prevalence of non-native speakers of a language (exotericity)—meaning that as the number of non-native speakers increases, grammatical complexity somewhat decreases, and vice versa—would be consistent, not inconsistent, with the LNH, since the text indicates that according to the LNH, there is an inverse relationship between grammatical complexity and exotericity; a negative correlation reflects an inverse relationship. Choice C is incorrect because it wouldn’t be possible to say that a finding of a slightly positive correlation between grammatical complexity and fusion is inconsistent or consistent with the LNH, since the finding would address only grammatical complexity (given that fusion is a positive indication of grammatical complexity) and wouldn’t move beyond that factor to address its relationship to the prevalence of non-native speakers of a language (exotericity), which is the relationship the LNH focuses on."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it most logically completes the text’s discussion of the evidence found in Queen Merneith’s tomb. The text begins by mentioning archaeologists’ efforts to excavate the tomb of Queen Merneith, the wife of a pharaoh who some scholars think was actually the first female pharaoh. The text states that a tablet discovered in her tomb suggests she “was in charge of the country’s treasury and other central offices,” which supports the idea that she had an important role in Egypt’s government."}, {"type": "paragraph", "text": "Choice B is incorrect because since the text explicitly states that Merneith’s husband was a First Dynasty pharaoh, it can be inferred that she lived during the First Dynasty, not after it. Choice C is incorrect because the text does not provide any evidence that Merneith traveled beyond Egypt’s borders often. The text is focused on the archaeological discovery in her tomb and the implications about her potential role as a ruler in Egypt but does not mention anything about her traveling habits. Choice D is incorrect because the text does not mention anything about Merneith creating a new form of writing in Egypt. The text discusses the discovery of a tablet with writing suggesting her governmental role but does not imply that this writing represented a new form created by Merneith."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most logically completes the text?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer because it presents the conclusion that most logically follows from the text’s discussion of the study of capuchin monkeys’ cognitive abilities. The text explains that the study failed to distinguish between outcomes for the tasks performed by the capuchin monkeys, such that simpler tasks requiring less dexterity, or skill, were judged by the same criteria as tasks that demanded more dexterity. Because the study didn’t account for this discrepancy, the researchers might have assumed that observed differences in performance were due to the abilities of the monkeys rather than the complexity of the tasks. In other words, the results may suggest cognitive differences among the monkeys even though such differences may not really exist."}, {"type": "paragraph", "text": "Choice B is incorrect because the text focuses on the fact that the tasks assigned to the capuchin monkeys in the study varied in difficulty and that the variety wasn’t taken into consideration. The text doesn’t suggest that the capuchin monkeys couldn’t perform certain tasks, just that some tasks were more difficult to do. Choice C is incorrect because the text doesn’t suggest that the study’s results are indicative of the abilities of capuchin monkeys but not of other monkey species; in fact, the text suggests that the results may not even be an accurate reflection of capuchin monkeys’ abilities. Choice D is incorrect because the text doesn’t indicate that the researchers compared results for artificial tasks with those for tasks encountered in the wild, although the tasks described in the text—sliding a panel and putting a straw in a bottle—are presumably artificial."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is pronoun-antecedent agreement. The plural pronoun “they” agrees in number with the plural antecedent “customers.”"}, {"type": "paragraph", "text": "Choice B is incorrect because the singular pronoun “one” doesn’t agree in number with the plural antecedent “customers.” Choice C is incorrect because the second person pronoun “you” isn’t conventional as a substitute for “customers.” It suggests that the audience (“you”) is the customer. Choice D is incorrect because the singular pronoun “it” doesn’t agree in number with the plural antecedent “customers.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is end-of-sentence punctuation. This choice correctly uses a question mark to punctuate the interrogative clause “could the blueberries thrive,” which asks a direct question at the end of the sentence."}, {"type": "paragraph", "text": "Choice A is incorrect because a period can’t be used in this way to punctuate an interrogative clause, such as “could the blueberries thrive,” at the end of a sentence. Choice B is incorrect because the context requires an interrogative clause. The declarative clause “the blueberries could thrive” incorrectly indicates that it was known that the blueberries could thrive in alkaline soil, whereas Michel had yet to find this out. Choice C is incorrect because a question mark can’t be used in this way to punctuate a declarative clause, such as “the blueberries could thrive,” at the end of a sentence."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. The convention being tested is the use of verbs to express tense in a sentence. In this choice, the present tense verb “reach” is consistent with the present tense verbs “travel” and “are diverted” used to describe how atoms move through the synchrotron."}, {"type": "paragraph", "text": "Choice A is incorrect because the future tense verb “will reach” is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. Though the atoms’ movement is a recurring action and “will reach” can also be used to indicate a habitual or recurring action, it creates a logical inconsistency in this sentence when paired with the present tense verbs “travel” and “are diverted.” Choice C is incorrect because the past perfect tense verb “had reached” is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. Choice D is incorrect because the present progressive tense verb “are reaching” is inconsistent with the present tense verbs used to describe how atoms move through the synchrotron. While both verbs occur in the present, the present progressive tense suggests that the action is currently in progress. This creates a logical inconsistency when paired with the present tense verbs “travel” and “are diverted,” which offer a general description of the tendencies of the atoms’ movement, rather than a description of an action that is currently in progress."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 20, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is the use of verbs to express tense. In this choice, the present tense verb “is,” used in conjunction with the word “today,” correctly indicates that Paik is currently considered the first video artist."}, {"type": "paragraph", "text": "Choice A is incorrect because the future tense verb “will be” doesn’t indicate that Paik is currently considered the first video artist. Choice B is incorrect because the past perfect tense verb “had been” doesn’t indicate that Paik is currently considered the first video artist. Choice C is incorrect because the past tense verb “was” doesn’t indicate that Paik is currently considered the first video artist."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 21, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The convention being tested is subject-verb agreement. The singular verb “outlines” agrees in number with the singular subject “document.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “have outlined” doesn’t agree in number with the singular subject “document.” Choice B is incorrect because the plural verb “were outlining” doesn’t agree in number with the singular subject “document.” Choice D is incorrect because the plural verb “outline” doesn’t agree in number with the singular subject “document.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is the use of punctuation within a sentence. In this choice, the colon correctly introduces the series of goals held by the 1919 Inter-Allied Women’s Conference."}, {"type": "paragraph", "text": "Choice B is incorrect because placing a period after “threefold” results in a rhetorically unacceptable sentence fragment beginning with “To.” Choice C is incorrect because it results in a run-on sentence. The main clause (“The conference’s goals were threefold”) and the series supplement (“to…rights”) are fused without punctuation. Choice D is incorrect because a semicolon can’t be used in this way to introduce a series. A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce a series, making the colon the better choice in this context."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb “is credited” agrees in number with the singular subject “mathematician Grigori Perelman.”"}, {"type": "paragraph", "text": "Choice A is incorrect because the plural verb “are credited” doesn’t agree in number with the singular subject “mathematician Grigori Perelman.” Choice B is incorrect because the plural verb “have been credited” doesn’t agree in number with the singular subject “mathematician Grigori Perelman.” Choice C is incorrect because the plural verb “are being credited” doesn’t agree in number with the singular subject “mathematician Grigori Perelman.”"}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text so that it conforms to the conventions of Standard English?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. The convention being tested is colon use within a sentence. A colon used in this way introduces information that illustrates or explains information that has come before it. In this case, the colon introduces the following explanation of why some roundworms in the Southern Hemisphere move in the opposite direction of Earth’s magnetic field."}, {"type": "paragraph", "text": "Choice B is incorrect because it results in a comma splice. A comma can’t be used in this way to join two long independent clauses (“Researchers…food” and “in… sources”) such as these. Choice C is incorrect because it results in a run-on sentence. The two clauses (“Researchers…food” and “in…sources”) are fused without punctuation. Furthermore, the conjunction “while” fails to indicate that what follows is an explanation of why some roundworms in the Southern Hemisphere move in the opposite direction of Earth’s magnetic field. Choice D is incorrect because it results in a run-on sentence. The two clauses (“Researchers… food” and “in…sources”) are fused without punctuation and/or a conjunction."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Standard English Conventions'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “For instance” logically signals that the information in this sentence—that larch trees lose their needles every fall—is an example supporting the claim in the previous sentence (that not all conifer species keep their leaves or needles year-round)."}, {"type": "paragraph", "text": "Choice B is incorrect because “nevertheless” illogically signals that the information in this sentence is true in spite of the claim about conifer species in the previous sentence. Instead, it’s an example supporting that claim. Choice C is incorrect because “meanwhile” illogically signals that the information in this sentence is separate from (while occurring simultaneously with) the claim about conifer species in the previous sentence. Instead, it’s an example supporting that claim. Choice D is incorrect because “in addition” illogically signals that the information in this sentence is merely an additional fact related to the claim about conifer species in the previous sentence. Instead, it’s an example supporting that claim."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice B is the best answer. “Next” logically signals that the action described in this sentence—Konkoly recording participants’ eye movements—is the next step in Konkoly’s experiment."}, {"type": "paragraph", "text": "Choice A is incorrect because “specifically” illogically signals that this sentence specifies or elaborates on an aspect of the action described in the previous sentence. Instead, it describes the next step in Konkoly’s experiment. Choice C is incorrect because “for instance” illogically signals that the action described in this sentence is an example of the action described in the previous sentence. Instead, it is the next step in Konkoly’s experiment. Choice D is incorrect because “in sum” illogically signals that this sentence summarizes or concludes the action described in the previous sentence. Instead, it describes the next step in Konkoly’s experiment."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 27, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Specifically” logically signals that the information in this sentence about Sauer’s argument—that, according to Sauer, cultures play a role in their own development, as opposed to being shaped solely by natural surroundings—provides specific, precise details elaborating on the more general information in the previous sentence about how Sauer challenged prevailing views about how natural landscapes influence human cultures."}, {"type": "paragraph", "text": "Choice A is incorrect because “similarly” illogically signals that the information in this sentence about Sauer’s argument is similar to, but separate from, the more general information in the previous sentence. Instead, it provides specific, precise details elaborating on that information. Choice B is incorrect because “finally” illogically signals that the information in this sentence about Sauer’s argument indicates a last step in a process or a concluding summary. Instead, it provides specific, precise details elaborating on the general information in the previous sentence. Choice C is incorrect because “therefore” illogically signals that the information in this sentence about Sauer’s argument is a result of the more general information in the previous sentence. Instead, it provides specific, precise details elaborating on that information."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 28, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. “Fittingly” logically signals that the naming of an unprecedented radiocarbon surge for Fusa Miyake is appropriate to the situation, since Miyake is the person who identified the surge (through her Yaku Island tree-ring analysis)."}, {"type": "paragraph", "text": "Choice B is incorrect because “similarly” illogically signals that the information in this sentence is similar to the previous information about Miyake’s identification of a massive radiation burst through tree-ring analysis. Instead, the naming of the event for its discoverer is a fitting and appropriate outcome. Choice C is incorrect because “however” illogically signals that the information in this sentence contrasts with the previous information about Miyake’s identification of a massive radiation burst through tree-ring analysis. Instead, the naming of the event for its discoverer is a fitting and appropriate outcome. Choice D is incorrect because “in other words” illogically signals that the information in this sentence is a paraphrase or restatement of the previous information about Miyake’s identification of a massive radiation burst through tree-ring analysis. Instead, the naming of the event for its discoverer is a fitting and appropriate outcome."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 29, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice completes the text with the most logical transition?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. “Increasingly” logically signals that the claim in this sentence— that mathematicians are collaborating with their peers—marks a change relative to what was traditionally done. As the previous sentence explains, while mathematicians may have traditionally worked alone, evidence points to a shift in the opposite direction. The claim describes the shift: a rise in collaboration."}, {"type": "paragraph", "text": "Choice A is incorrect because “similarly” illogically signals that the claim in this sentence is similar to, but separate from, the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. Choice B is incorrect because “for this reason” illogically signals that the claim in this sentence is caused by the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift. Choice C is incorrect because “furthermore” illogically signals that the claim in this sentence is in addition to the previous claim about the shift away from mathematicians working alone. Instead, the claim about the rise in collaboration elaborates on the previous claim, describing the shift."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Expression of Ideas'), 'medium', 'source', 'approved', 30, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice D is the best answer. The sentence uses “both” to emphasize a thematic similarity between Tan’s two books, noting that both Tales from Outer Suburbia and Tales from the Inner City describe surreal events occurring in otherwise ordinary places."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence emphasizes a difference (one contains fewer stories than the other), not a similarity, between the two books. Choice B is incorrect. The sentence indicates that Tan’s books were published ten years apart; it doesn’t emphasize a similarity between the two books. Choice C is incorrect. The sentence uses “unlike” to emphasize a difference between Tales from Outer Suburbia and Tales from the Inner City; it doesn’t emphasize a similarity between the two books."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 31, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice A is the best answer. Noting that “guerdon” is of Anglo-French origin and “Laodicean” is of ancient Greek origin, the sentence uses “while” to emphasize a difference in the origins of the two words."}, {"type": "paragraph", "text": "Choice B is incorrect. While the sentence emphasizes two words used in the Scripps National Spelling Bee, it doesn’t emphasize (or mention) the words’ linguistic origins. Choice C is incorrect. While the sentence specifies the linguistic origin of one word used in the Scripps National Spelling Bee, it doesn’t mention the other word or emphasize a difference in the two words’ origins. Choice D is incorrect. While the sentence makes a generalization about words used in the Scripps National Spelling Bee, it doesn’t emphasize a difference in the words’ origins."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 32, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, v_stim, null, '{"blocks": [{"type": "paragraph", "text": "Which choice most effectively uses relevant information from the notes to accomplish this goal?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Choice C is the best answer. The sentence emphasizes a similarity between the two paintings, noting that Leutze’s painting (which measures 149 × 255 inches) and Monkman’s painting (which measures 132 × 264 inches) are both very large."}, {"type": "paragraph", "text": "Choice A is incorrect. The sentence mentions that Monkman’s painting was completed in 2019 and Leutze’s was completed in 1851; it doesn’t emphasize a similarity between the two paintings. Choice B is incorrect. While the sentence acknowledges that one painting was inspired by the other, it emphasizes differences between the two paintings; it doesn’t emphasize a similarity between them. Choice D is incorrect. The sentence mentions a difference between the two paintings; it doesn’t emphasize a similarity between them."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Information and Ideas'), 'medium', 'source', 'approved', 33, 'choice', array[]::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
  -- SAT Practice Test 10: Math
  if exists (select 1 from public.exams where slug = 'sat-practice-test-10-math') then
    raise notice 'skipping sat-practice-test-10-math (already imported)';
  else
    select id into v_subject from public.subjects where code = 'sat-math';
    values (v_subject, 'sat-practice-test-10-math', 'SAT Practice Test 10: Math', 'Official SAT Practice Test 10 (College Board), Math: 54 questions in two modules, including student-produced responses. Calculator allowed; 43 minutes per module.', 'full_mock', 'premium', 'draft', 86, 'source', 221, '[[200, 200], [210, 220], [210, 220], [210, 220], [210, 230], [210, 240], [220, 250], [230, 260], [240, 300], [250, 310], [260, 320], [280, 340], [310, 350], [320, 360], [330, 370], [340, 380], [350, 390], [360, 400], [370, 410], [380, 420], [380, 420], [390, 430], [390, 430], [400, 440], [410, 450], [420, 460], [430, 470], [440, 480], [450, 490], [460, 500], [470, 510], [480, 520], [490, 530], [490, 550], [510, 570], [520, 580], [530, 590], [540, 600], [550, 610], [560, 620], [580, 640], [590, 650], [600, 660], [610, 670], [620, 680], [640, 700], [650, 710], [670, 730], [680, 740], [700, 760], [730, 770], [750, 780], [770, 790], [780, 800], [800, 800]]'::jsonb)
    returning id into v_exam;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m1-q01.png", "alt": "Figure for question 1", "width": 310}, {"type": "paragraph", "text": "The line graph shows the percent of cars for sale at a used car lot on a given day by model year."}, {"type": "paragraph", "text": "For what model year is the percent of cars for sale the smallest?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The lowest point on the graph, about $4\\%$, is at $2014$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m1-q02.png", "alt": "Figure for question 2", "width": 262}, {"type": "paragraph", "text": "The graph of a system of linear equations is shown. What is the solution $(x, y)$ to the system?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The two lines intersect at $(4, -5)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The total cost, in dollars, to rent a surfboard consists of a $\\$25$ service fee and a $\\$10$ per hour rental fee. A person rents a surfboard for $t$ hours and intends to spend a maximum of $\\$75$ to rent the surfboard. Which inequality represents this situation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The cost is the $\\$25$ fee plus $\\$10$ for each of $t$ hours, and it can be at most $\\$75$: $25 + 10t \\le 75$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m1-q04.png", "alt": "Figure for question 4", "width": 266}, {"type": "paragraph", "text": "The graph shown will be translated up $4$ units. Which of the following will be the resulting graph?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The vertex $(2, -2)$ moves up $4$ units to $(2, 2)$, and the shape stays the same. Graph A has vertex $(2, 2)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "s = 40 + 3t"}, {"type": "paragraph", "text": "The equation gives the speed $s$, in miles per hour, of a certain car $t$ seconds after it began to accelerate. What is the speed, in miles per hour, of the car $5$ seconds after it began to accelerate?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$s = 40 + 3(5) = 55$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = x^2 + x + 71$. What is the value of $f(2)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(2) = 4 + 2 + 71 = 77$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 6, 'spr', array['77']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An event planner is planning a party. It costs the event planner a onetime fee of $\\$35$ to rent the venue and $\\$10.25$ per attendee. The event planner has a budget of $\\$300$. What is the greatest number of attendees possible without exceeding the budget?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$35 + 10.25n \\le 300$ gives $10.25n \\le 265$, so $n \\le 25.8\\ldots$. The greatest whole number is $25$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 7, 'spr', array['25']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m1-q08.png", "alt": "Figure for question 8", "width": 267}, {"type": "paragraph", "text": "The table gives the distribution of votes for a new school mascot and grade level for $80$ students."}, {"type": "paragraph", "text": "If one of these students is selected at random, what is the probability of selecting a student whose vote for new mascot was for a lion?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$20$ of the $80$ students voted for the lion: $\\tfrac{20}{80} = \\tfrac{1}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Triangles $ABC$ and $DEF$ are congruent, where $A$ corresponds to $D$, and $B$ and $E$ are right angles. The measure of angle $A$ is $18^\\circ$. What is the measure of angle $F$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Angle $C = 180 - 90 - 18 = 72^\\circ$, and angle $F$ corresponds to angle $C$, so it is $72^\\circ$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "If $4x + 2 = 12$, what is the value of $16x + 8$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$16x + 8 = 4(4x + 2) = 4(12) = 48$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $(m^4q^4z^{-1})(mq^5z^3)$, where $m$, $q$, and $z$ are positive?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Add the exponents of each base: $m^{4+1}q^{4+5}z^{-1+3} = m^5q^9z^2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An airplane descends from an altitude of $9{,}500$ feet to $5{,}000$ feet at a constant rate of $400$ feet per minute. What type of function best models the relationship between the descending airplane''s altitude and time?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The altitude falls by the same amount each minute, so the relationship is decreasing linear."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} 3x + 6 &= 4y \\\\ 3x + 4 &= 2y \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Subtract the second equation from the first: $2 = 2y$, so $y = 1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 13, 'spr', array['1']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = (x - 6)(x - 2)(x + 6)$. In the $xy$-plane, the graph of $y = g(x)$ is the result of translating the graph of $y = f(x)$ up $4$ units. What is the value of $g(0)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = (-6)(-2)(6) = 72$, and translating up $4$ units adds $4$: $g(0) = 76$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['76']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f(w) = 6w^2$ gives the area of a rectangle, in square feet (ft$^2$), if its width is $w$ ft and its length is $6$ times its width. Which of the following is the best interpretation of $f(14) = 1{,}176$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The input $14$ is the width in feet and the output $1{,}176$ is the area in square feet."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The number of bacteria in a liquid medium doubles every day. There are $44{,}000$ bacteria in the liquid medium at the start of an observation. Which of the following represents the number of bacteria, $y$, in the liquid medium $t$ days after the start of the observation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Start at $44{,}000$ and multiply by $2$ each day: $y = 44{,}000(2)^t$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "table", "header": ["$x$", "$h(x)$"], "rows": [["$0$", "$1.23$"], ["$2$", "$1.54$"], ["$4$", "$1.94$"]]}, {"type": "paragraph", "text": "The table shows the exponential relationship between the number of years, $x$, since Hana started training in pole vault, and the estimated height $h(x)$, in meters, of her best pole vault for that year. Which of the following functions best represents this relationship, where $x \\le 4$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$h(0) = 1.23$ is the initial value, and $\\tfrac{1.54}{1.23} \\approx 1.25 \\approx 1.12^2$, so the yearly growth factor is about $1.12$: $h(x) = 1.23(1.12)^x$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $h$ is defined by $h(x) = 4x + 28$. The graph of $y = h(x)$ in the $xy$-plane has an $x$-intercept at $(a, 0)$ and a $y$-intercept at $(0, b)$, where $a$ and $b$ are constants. What is the value of $a + b$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4a + 28 = 0$ gives $a = -7$, and $b = h(0) = 28$, so $a + b = 21$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "y < 5x + 6"}, {"type": "paragraph", "text": "For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$5x + 6$ equals $21$, $31$, and $41$ at $x = 3$, $5$, $7$. Only table A has every $y$ strictly less: $17$, $27$, $37$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= 4x + 1 \\\\ 4y &= 15x - 8 \\end{aligned}"}, {"type": "paragraph", "text": "The solution to the given system of equations is $(x, y)$. What is the value of $x - y$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Substitute: $4(4x + 1) = 15x - 8$, so $x = -12$ and $y = -47$. Then $x - y = -12 + 47 = 35$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 20, 'spr', array['35']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A right triangle has legs with lengths of $24$ centimeters and $21$ centimeters. If the length of this triangle''s hypotenuse, in centimeters, can be written in the form $3\\sqrt{d}$, where $d$ is an integer, what is the value of $d$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The hypotenuse is $\\sqrt{576 + 441} = \\sqrt{1{,}017} = \\sqrt{9 \\cdot 113} = 3\\sqrt{113}$, so $d = 113$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 21, 'spr', array['113']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The floor of a ballroom has an area of $600$ square meters. An architect creates a scale model of the floor of the ballroom, where the length of each side of the model is $\\dfrac{1}{10}$ times the length of the corresponding side of the actual floor of the ballroom. What is the area, in square meters, of the scale model?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Lengths scale by $\\tfrac{1}{10}$, so areas scale by $\\tfrac{1}{100}$: $\\tfrac{600}{100} = 6$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following equations represents a circle in the $xy$-plane that intersects the $y$-axis at exactly one point?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each circle has radius $4$. A circle touches the $y$-axis at exactly one point when its center is $4$ units from the axis, that is, its $x$-coordinate is $\\pm 4$. That is choice C, centered at $(4, 9)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In triangles $ABC$ and $DEF$, angles $B$ and $E$ each have measure $27^\\circ$ and angles $C$ and $F$ each have measure $41^\\circ$. Which additional piece of information is sufficient to determine whether triangle $ABC$ is congruent to triangle $DEF$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Two pairs of equal angles make the triangles similar. They are congruent only if a pair of corresponding sides is equal, so we need to compare the lengths of corresponding sides such as $BC$ and $EF$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The result of increasing the quantity $x$ by $1{,}800\\%$ is $684$. What is the value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Increasing by $1{,}800\\%$ multiplies by $1 + 18 = 19$: $19x = 684$, so $x = 36$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'medium', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A window repair specialist charges $\\$220$ for the first two hours of repair plus an hourly fee for each additional hour. The total cost for $5$ hours of repair is $\\$400$. Which function $f$ gives the total cost, in dollars, for $x$ hours of repair, where $x \\ge 2$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $3$ extra hours cost $400 - 220 = 180$ dollars, or $\\$60$ per hour. So $f(x) = 220 + 60(x - 2) = 60x + 100$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "x(x + 1) - 56 = 4x(x - 7)"}, {"type": "paragraph", "text": "What is the sum of the solutions to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Expand: $x^2 + x - 56 = 4x^2 - 28x$, so $3x^2 - 29x + 56 = 0$. The sum of the solutions is $\\tfrac{29}{3}$ (about $9.667$)."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 27, 'spr', array['29/3', '9.666', '9.667']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "An object''s speed is $64$ yards per second. What is the object''s speed, in **feet** per second? ($1$ yard $= 3$ feet)"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$64 \\times 3 = 192$ feet per second."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 1, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m2-q02.png", "alt": "Figure for question 2", "width": 256}, {"type": "paragraph", "text": "The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit is also shown."}, {"type": "paragraph", "text": "Which of the following equations best represents the line of best fit shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line rises (positive slope) and crosses the $y$-axis above $0$, near $3.4$: $y = x + 3.4$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 2, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m2-q03.png", "alt": "Figure for question 3", "width": 262}, {"type": "paragraph", "text": "The graph shows the linear relationship between $x$ and $y$. Which table gives three values of $x$ and their corresponding values of $y$ for this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line passes through $(0, -5)$, $(1, -3)$, and $(2, -1)$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 3, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "What is the perimeter, in inches, of a rectangle with a length of $4$ inches and a width of $9$ inches?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$2(4 + 9) = 26$ inches."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 4, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "7m = 2(n + p)"}, {"type": "paragraph", "text": "The given equation relates the positive numbers $m$, $n$, and $p$. Which equation correctly gives $m$ in terms of $n$ and $p$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Divide both sides by $7$: $m = \\dfrac{2(n + p)}{7}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 5, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "73, 74, 75, 77, 79, 82, 84, 85, 91"}, {"type": "paragraph", "text": "What is the median of the data shown?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The $9$ values are in order, so the median is the $5$th value: $79$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 6, 'spr', array['79']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = 4x$. For what value of $x$ does $f(x) = 8$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$4x = 8$, so $x = 2$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 7, 'spr', array['2']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Of $300{,}000$ paper clips, $234{,}000$ are size large. What percentage of the paper clips are size large?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$\\dfrac{234{,}000}{300{,}000} = 0.78$, or $78\\%$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'easy', 'source', 'approved', 8, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "f(x) = 8x + 4"}, {"type": "paragraph", "text": "The function $f$ gives the estimated height, in feet, of a willow tree $x$ years after its height was first measured. Which statement is the best interpretation of $4$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = 4$: when $x = 0$, at the first measurement, the estimated height was $4$ feet."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 9, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "\\begin{aligned} y &= 76 \\\\ y &= x^2 - 5 \\end{aligned}"}, {"type": "paragraph", "text": "The graphs of the given equations in the $xy$-plane intersect at the point $(x, y)$. What is a possible value of $x$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$x^2 - 5 = 76$, so $x^2 = 81$ and $x = 9$ or $-9$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'easy', 'source', 'approved', 10, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Each side of equilateral triangle S is multiplied by a scale factor of $k$ to create equilateral triangle T. The length of each side of triangle T is greater than the length of each side of triangle S. Which of the following could be the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "T''s sides are longer only if $k > 1$. Of the choices, only $\\tfrac{29}{28}$ is greater than $1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'easy', 'source', 'approved', 11, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "66x = 66x"}, {"type": "paragraph", "text": "How many solutions does the given equation have?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Both sides are identical, so every value of $x$ works: infinitely many solutions."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 12, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Vivian bought party hats and cupcakes for $\\$71$. Each package of party hats cost $\\$3$, and each cupcake cost $\\$1$. If Vivian bought $10$ packages of party hats, how many cupcakes did she buy?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The hats cost $10 \\times 3 = 30$ dollars, leaving $71 - 30 = 41$ dollars for $41$ cupcakes."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'easy', 'source', 'approved', 13, 'spr', array['41']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The exponential function $g$ is defined by $g(x) = 19 \\cdot a^x$, where $a$ is a positive constant. If $g(3) = 2{,}375$, what is the value of $g(4)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$19a^3 = 2{,}375$, so $a^3 = 125$ and $a = 5$. Then $g(4) = 19 \\cdot 625 = 11{,}875$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 14, 'spr', array['11875']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "In right triangle $RST$, the sum of the measures of angle $R$ and angle $S$ is $90$ degrees. The value of $\\sin(R)$ is $\\dfrac{\\sqrt{15}}{4}$. What is the value of $\\cos(S)$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "For complementary angles, the cosine of one equals the sine of the other: $\\cos(S) = \\sin(R) = \\tfrac{\\sqrt{15}}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 15, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m2-q16.png", "alt": "Figure for question 16", "width": 291}, {"type": "paragraph", "text": "The graph shows the relationship between the number of shares of stock from Company A, $x$, and the number of shares of stock from Company B, $y$, that Simone can purchase. Which equation could represent this relationship?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The line has intercepts $(60, 0)$ and $(0, 40)$. In $8x + 12y = 480$, $y = 0$ gives $x = 60$ and $x = 0$ gives $y = 40$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 16, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which expression is equivalent to $\\dfrac{8x(x - 7) - 3(x - 7)}{2x - 14}$, where $x > 7$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Factor: $\\dfrac{(x - 7)(8x - 3)}{2(x - 7)} = \\dfrac{8x - 3}{2}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 17, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The function $f$ is defined by $f(x) = (-8)(2)^x + 22$. What is the $y$-intercept of the graph of $y = f(x)$ in the $xy$-plane?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$f(0) = -8(1) + 22 = 14$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'medium', 'source', 'approved', 18, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Keenan made $32$ cups of vegetable broth. Keenan then filled $x$ small jars and $y$ large jars with all the vegetable broth he made. The equation $3x + 5y = 32$ represents this situation. Which is the best interpretation of $5y$ in this context?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each large jar holds $5$ cups and there are $y$ of them, so $5y$ is the total broth in the large jars."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 19, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "A circle in the $xy$-plane has a diameter with endpoints $(2, 4)$ and $(2, 14)$. An equation of this circle is $(x - 2)^2 + (y - 9)^2 = r^2$, where $r$ is a positive constant. What is the value of $r$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The diameter has length $14 - 4 = 10$, so $r = 5$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'medium', 'source', 'approved', 20, 'spr', array['5']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Line $\\ell$ is defined by $3y + 12x = 5$. Line $n$ is perpendicular to line $\\ell$ in the $xy$-plane. What is the slope of line $n$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Line $\\ell$: $y = -4x + \\tfrac{5}{3}$, slope $-4$. A perpendicular line has slope $\\tfrac{1}{4}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'medium', 'source', 'approved', 21, 'spr', array['0.25', '1/4']::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "|-5x + 13| = 73"}, {"type": "paragraph", "text": "What is the sum of the solutions to the given equation?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "$-5x + 13 = 73$ gives $x = -12$, and $-5x + 13 = -73$ gives $x = \\tfrac{86}{5}$. The sum is $\\tfrac{86}{5} - 12 = \\tfrac{26}{5}$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Algebra'), 'hard', 'source', 'approved', 22, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "For the exponential function $f$, the value of $f(1)$ is $k$, where $k$ is a constant. Which of the following equivalent forms of the function $f$ shows the value of $k$ as the coefficient or the base?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "In $f(x) = 128(1.6)^{x-1}$, $f(1) = 128(1.6)^0 = 128$, which is the coefficient."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 23, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "math", "latex": "-9x^2 + 30x + c = 0"}, {"type": "paragraph", "text": "In the given equation, $c$ is a constant. The equation has exactly one solution. What is the value of $c$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Exactly one solution means the discriminant is $0$: $30^2 - 4(-9)(c) = 900 + 36c = 0$, so $c = -25$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 24, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "Which of the following expressions has a factor of $x + 2b$, where $b$ is a positive integer constant?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "If $x + 2b$ is a factor, the expression is $(x + 2b)(3x + 7) = 3x^2 + (7 + 6b)x + 14b$. Then $7 + 6b = 49$ gives the integer $b = 7$; $28$ and $42$ do not give integers, and $7$ gives $b = 0$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Advanced Math'), 'hard', 'source', 'approved', 25, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "image", "src": "/sat/test-10/math-m2-q26.png", "alt": "Figure for question 26", "width": 324}, {"type": "paragraph", "text": "Two data sets of $23$ integers each are summarized in the histograms shown. For each of the histograms, the first interval represents the frequency of integers greater than or equal to $10$, but less than $20$. The second interval represents the frequency of integers greater than or equal to $20$, but less than $30$, and so on. What is the smallest possible difference between the mean of data set A and the mean of data set B?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "The histograms have the same frequencies, but each bar for A is one interval higher. To make the means as close as possible, put A''s values at the bottom of each interval and B''s at the top: each A value is then at least $1$ more than its B partner (for example $20$ versus $19$), so the means differ by at least $1$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Problem-Solving and Data Analysis'), 'hard', 'source', 'approved', 26, 'choice', array[]::text[]) returning id into v_q;
    values (v_subject, null, null, '{"blocks": [{"type": "paragraph", "text": "The perimeter of an equilateral triangle is $624$ centimeters. The height of this triangle is $k\\sqrt{3}$ centimeters, where $k$ is a constant. What is the value of $k$?"}]}'::jsonb, '{"blocks": [{"type": "paragraph", "text": "Each side is $208$, and the height of an equilateral triangle is $\\tfrac{\\sqrt{3}}{2}$ times the side: $104\\sqrt{3}$. So $k = 104$."}]}'::jsonb, (select id from public.topics where subject_id = v_subject and kind = 'topic' and name = 'Geometry and Trigonometry'), 'hard', 'source', 'approved', 27, 'spr', array['104']::text[]) returning id into v_q;
    update public.exams set status = 'published' where id = v_exam;
  end if;
end $sat$;
